"""Local application server; save state lives in state/world.sqlite3."""
import argparse, gzip, hashlib, io, json, mimetypes, re, secrets, sys, tempfile, threading, time
from http.server import BaseHTTPRequestHandler,ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs,urlsplit,unquote
import world
from ai import Claude,Runner
from store import Store,validate_world
from admin import Authority
from operator_loop import WorldClock

ROOT=Path(__file__).parent
JSON_IMPORT_LIMIT=128*1024*1024
DATABASE_IMPORT_LIMIT=16*1024*1024*1024
# 그림 전송 규칙(코덱스 배경 계약 v1): 게임 상태는 저장 금지, 배경 목록은 매번 확인(ETag), 내용 해시 이름 그림은 오래 둔다
BACKGROUND_LIST='backgrounds-v1.json'
HASHED_ASSET=re.compile(r'^(asset-[0-9a-f]{20}|[A-Za-z0-9_-]+\.[0-9a-f]{16})\.webp$')
CACHE_REVALIDATE='no-cache';CACHE_FOREVER='public, max-age=31536000, immutable'

class App:
    def __init__(self,db):
        self.store=Store(db);self.claude=Claude();self.runner=Runner(self.store,self.claude);self.operations=threading.RLock()
        self.authority=Authority(Path(db).parent);self.clock=WorldClock(self)
    def initialize_clock_policy(self):
        with self.operations:
            if not self.store.setting('automaticRulesPolicy',False):
                self.clock.configure({'enabled':True,'provider':'rules','intervalSeconds':600});self.store.set_setting('automaticRulesPolicy',True)
    def status(self,admin=False):
        acquired=self.operations.acquire(blocking=False)
        try:
            w=self.store.load();job=self.store.active()
            if acquired and job and job['status'] in ['running','queued'] and not(self.runner.thread and self.runner.thread.is_alive()):
                job.update(status='failed',error=self.runner.last_error or '행동 생성 실행이 중단됐습니다.',message='완료한 묶음을 보존했습니다. 관리자가 이어갈 수 있습니다.');self.store.update_job(job)
        finally:
            if acquired:self.operations.release()
        if job and not admin:job={k:job[k] for k in ['status','provider','message','doneBatches','totalBatches','completedMonths','months']}
        return {'world':world.summary(w),'activeJob':job,'clock':self.clock.status(),'claude':self.claude.status() if admin else {'loggedIn':False,'message':'세계 운영은 관리자 화면에서 진행합니다.'},'recent':self.store.events(kind='story',limit=12)['items'],'eventCount':self.store.events(limit=1)['total']}
    def advance(self,provider,months):
        with self.operations:
            if provider not in ['claude','rules'] or type(months) is not int or not 1<=months<=120 or (provider=='claude' and months!=1):raise ValueError('Claude는 한 번에 한 달, 빠른 검증은 최대 120개월씩 진행합니다.')
            if provider=='claude' and not self.claude.status(True)['loggedIn']:raise ValueError('Claude Code 로그인이 필요합니다.')
            with self.runner.lock:
                if self.runner.thread and self.runner.thread.is_alive():raise ValueError('현재 작업이 끝나기를 기다려 주세요.')
            j=self.store.new_job(provider,months);self.runner.start(j)
            if self.clock.config['enabled']:
                self.clock.config.update(lastJob=j['id'],nextRun=None);self.clock.save()
            return j
    def mutate(self,kind,value):
        with self.operations,self.store.lock:
            if self.store.active():raise ValueError('행동 생성 중에는 인물·세계 설정을 바꾸지 않습니다. 먼저 완료하거나 취소해 주세요.')
            w=self.store.load();rev=w['revision']
            if kind=='arrive':
                if not isinstance(value,int) or not 1<=value<=1000:raise ValueError('한 번의 유입은 1~1,000명으로 입력해 주세요. 누적 인물 수의 상한은 없습니다.')
                world.arrive(w,value,'관리자가 추가한 새 시드 인물의 유입')
            elif kind=='config':
                n=value.get('arrivalsPerYear')
                if not isinstance(n,int) or not 0<=n<=1000:raise ValueError('연간 유입 인원은 0~1,000명으로 설정할 수 있습니다.')
                w['config']['arrivalsPerYear']=n;world.emit(w,'world_policy',[],f'연간 새 인물 유입을 {n}명으로 설정했다.',arrivalsPerYear=n)
            w['revision']+=1;validate_world(w);self.store.commit(w,rev)
            return world.summary(w)
    def player_birth(self,basis):
        """Roll and record the player's birth into the running world (one living player at a time)."""
        if basis not in ['population','births']:raise ValueError('출생 기준은 지금 사는 사람(population) 또는 지금 태어나는 아기(births)입니다.')
        with self.operations,self.store.lock:
            if self.store.active():raise ValueError('세계가 한 달을 진행하는 중입니다. 끝난 뒤 다시 태어나기를 눌러 주세요.')
            w=self.store.load();rev=w['revision']
            if w.get('schema',3)<7:raise ValueError('이 세계는 아직 출생 기능이 없는 저장 형식입니다.')
            roll=world.roll_birth(w,basis,secrets.randbits(48));child=world.player_birth(w,roll)
            w['revision']+=1;validate_world(w);self.store.commit(w,rev)
            return {'roll':roll,'person':world.public_person(w,child),'world':world.summary(w)}

class Handler(BaseHTTPRequestHandler):
    server_version='ProtLocal/0.4'
    def log_message(self,format,*args):pass
    @property
    def app(self):return self.server.app
    def send(self,data,status=200,content_type='application/json; charset=utf-8',filename=None,cookie=None,cache='no-store',etag=None):
        b=data if isinstance(data,bytes) else json.dumps(data,ensure_ascii=False).encode()
        self.send_response(status);self.send_header('Content-Type',content_type);self.send_header('Content-Length',str(len(b)))
        self.send_header('Cache-Control',cache);self.send_header('X-Content-Type-Options','nosniff')
        if etag:self.send_header('ETag',etag)
        if filename:self.send_header('Content-Disposition',f'attachment; filename="{filename}"')
        if cookie:self.send_header('Set-Cookie',cookie)
        self.end_headers();self.wfile.write(b)
    def send_asset(self,f):
        """그림과 배경 목록: 목록은 ETag로 바뀐 것만 다시 받고, 해시 이름 그림은 1년 둔다."""
        if not f.is_file():return self.send({'error':'파일이 없습니다.'},404)
        b=f.read_bytes()
        if f.name==BACKGROUND_LIST:
            tag='"'+hashlib.sha256(b).hexdigest()[:32]+'"'
            if tag in [x.strip() for x in self.headers.get('If-None-Match','').split(',')]:
                self.send_response(304);self.send_header('ETag',tag);self.send_header('Cache-Control',CACHE_REVALIDATE);self.end_headers();return
            return self.send(b,content_type='application/json; charset=utf-8',cache=CACHE_REVALIDATE,etag=tag)
        return self.send(b,content_type='image/webp',cache=CACHE_FOREVER if HASHED_ASSET.match(f.name) else CACHE_REVALIDATE)
    def send_database(self):
        folder=(self.app.store.path.parent/'export-staging').resolve();folder.mkdir(exist_ok=True)
        with tempfile.TemporaryDirectory(dir=folder,prefix='save-') as temp:
            if not Path(temp).resolve().is_relative_to(folder):raise ValueError('저장 경로를 확인하지 못했습니다.')
            target=Path(temp)/'world.sqlite3';self.app.store.backup_database(target)
            self.send_response(200);self.send_header('Content-Type','application/x-sqlite3');self.send_header('Content-Length',str(target.stat().st_size));self.send_header('Cache-Control','no-store');self.send_header('X-Content-Type-Options','nosniff');self.send_header('Content-Disposition','attachment; filename="prot-world.sqlite3"');self.end_headers()
            with target.open('rb') as f:
                while block:=f.read(1024*1024):self.wfile.write(block)
    def receive_database(self,prefix,length):
        folder=(self.app.store.path.parent/'import-staging').resolve();folder.mkdir(exist_ok=True)
        with tempfile.TemporaryDirectory(dir=folder,prefix='load-') as temp:
            if not Path(temp).resolve().is_relative_to(folder):raise ValueError('불러오기 경로를 확인하지 못했습니다.')
            target=Path(temp)/'world.sqlite3'
            with target.open('wb') as f:
                f.write(prefix);remaining=length-len(prefix)
                while remaining:
                    block=self.rfile.read(min(remaining,1024*1024))
                    if not block:raise ValueError('저장 파일 전송이 중단됐습니다.')
                    f.write(block);remaining-=len(block)
            with self.app.operations:
                self.app.store.restore_database(target);self.app.clock.configure({'enabled':False})
        return self.send(self.app.status(True))
    def do_GET(self):
        try:
            host=self.headers.get('Host','')
            if host not in [f'127.0.0.1:{self.server.server_port}',f'localhost:{self.server.server_port}']:return self.send({'error':'이 컴퓨터의 게임 화면에서 접속해 주세요.'},403)
            u=urlsplit(self.path);path=unquote(u.path);q=parse_qs(u.query)
            arg=lambda k,default=None:q.get(k,[default])[0]
            admin=self.app.authority.authenticated(self.headers.get('Cookie'))
            if path=='/api/admin/access':return self.send({'authenticated':admin})
            if path in ['/api/admin/status','/api/claude','/api/audit','/api/export'] and not admin:return self.send({'error':'관리자 인증이 필요합니다.'},403)
            if path=='/api/health':return self.send({'app':'shield-prot-v3','ok':True})
            if path in ['/api/status','/api/admin/status']:return self.send(self.app.status(path=='/api/admin/status'))
            if path=='/api/claude':return self.send(self.app.claude.status(arg('refresh')=='1'))
            if path=='/api/people':
                w=self.app.store.load();rows=list(w['people'].values());search=arg('search','').strip();region=arg('region','ALL');alive=arg('alive','ALL')
                if region!='ALL':rows=[p for p in rows if p['region']==region]
                if alive!='ALL':rows=[p for p in rows if p['alive']==(alive=='1')]
                if search:rows=[p for p in rows if search in ' '.join([p['id'],p['name'],p['race'],p.get('householdId') or '',*p['biologicalParents'],*[x.get('name','') for x in p['nameHistory']]])]
                sort=arg('sort','id')
                rows.sort(key=(lambda p:p['birthMonth']) if sort=='new' else (lambda p:-world.life_total(p)) if sort=='score' else (lambda p:(not p['id'].startswith('P'),int(p['id'][1:]) if p['id'].startswith('P') else p['id'])))
                offset=max(0,int(arg('offset','0')));limit=min(100,max(1,int(arg('limit','30'))))
                items=[{'id':p['id'],'name':p['name'],'age':world.age(p,w['month']),'race':p['race'],'country':p['country'],'region':p['region'],'alive':p['alive'],'parents':p['biologicalParents'],'household':p['householdId'],'job':p['job'],'cash':p['cash'],'health':round(p['health']),'art':p['art'],'score':world.life_total(p)} for p in rows[offset:offset+limit]]
                return self.send({'total':len(rows),'items':items,'month':w['month']})
            if path.startswith('/api/person/'):
                pid=path.removeprefix('/api/person/');w=self.app.store.load()
                if pid not in w['people']:return self.send({'error':'인물 기록을 찾지 못했습니다.'},404)
                p=world.public_person(w,w['people'][pid]);return self.send({'person':p,'names':{x:w['people'][x]['name'] for x in {*p['biologicalParents'],*p['legalParents'],*p['children'],*p['founders'],*([p['guardian']] if p['guardian'] else []),*([p['spouse']] if p['spouse'] else [])}},'history':self.app.store.events(person=pid,offset=int(arg('offset','0')),limit=40)})
            if path=='/api/birth/odds':
                w=self.app.store.load()
                if w.get('schema',3)<7:return self.send({'error':'이 세계는 아직 출생 기능이 없는 저장 형식입니다.'},409)
                return self.send(world.birth_odds(w,arg('basis','population')))
            if path=='/api/events':return self.send(self.app.store.events(person=arg('person'),kind=arg('kind'),offset=int(arg('offset','0')),limit=int(arg('limit','40'))))
            if path=='/api/estates':
                w=self.app.store.load();cases=sorted(w['estates'].values(),key=lambda c:c['month'],reverse=True)
                ids={c['deceased'] for c in cases}
                for c in cases:ids.update(c.get('weights',{}))
                return self.send({'items':cases[:100],'total':len(cases),'names':{x:w['people'][x]['name'] for x in ids if x in w['people']}})
            if path=='/api/audit':
                records=self.app.store.audit(arg('job'));return self.send([{'jobId':r['jobId'],'month':r['month'],'batch':r['batch'],'count':len(r['intents']),'provider':r['provider'],'realClaudeCall':r.get('realClaudeCall',False),'seconds':r.get('seconds',0),'responseSha256':r.get('responseSha256'),'sample':r['intents'][:3]} for r in records[-150:]])
            if path=='/api/export':
                if arg('format')!='json':return self.send_database()
                data=self.app.store.export();blob=gzip.compress(json.dumps(data,ensure_ascii=False,separators=(',',':')).encode())
                return self.send(blob,content_type='application/gzip',filename=f'prot-world-month-{data["state"]["month"]}.json.gz')
            allowed={'/':'index.html','/index.html':'index.html','/admin':'index.html','/admin/':'index.html','/app.js':'app.js','/styles.css':'styles.css','/guide.html':'guide.html'}
            if path in allowed:f=ROOT/'web'/allowed[path]
            elif path.startswith('/assets/') and path[8:] in {p.name for p in (ROOT/'web'/'assets').glob('*.webp')}|{BACKGROUND_LIST}:return self.send_asset(ROOT/'web'/'assets'/path[8:])
            else:return self.send({'error':'페이지를 찾지 못했습니다.'},404)
            if not f.is_file():return self.send({'error':'파일이 없습니다.'},404)
            return self.send(f.read_bytes(),content_type=(mimetypes.guess_type(f.name)[0] or 'application/octet-stream')+('; charset=utf-8' if f.suffix in ['.html','.css','.js'] else ''))
        except (ValueError,KeyError,TypeError) as e:self.send({'error':str(e)},400)
        except (BrokenPipeError,ConnectionResetError):pass
        except Exception as e:self.send({'error':'요청을 처리하지 못했습니다. 저장된 세계는 유지됩니다.','detail':type(e).__name__},500)
    def do_POST(self):
        try:
            host=self.headers.get('Host','');origin=self.headers.get('Origin')
            if host not in [f'127.0.0.1:{self.server.server_port}',f'localhost:{self.server.server_port}'] or (origin and origin not in ['http://'+host]):return self.send({'error':'이 컴퓨터의 게임 화면에서 요청해 주세요.'},403)
            path=urlsplit(self.path).path
            if path not in ['/api/admin/login','/api/player/birth'] and not self.app.authority.authenticated(self.headers.get('Cookie')):return self.send({'error':'세계 운영과 인물 추가는 관리자만 할 수 있습니다.'},403)
            length=int(self.headers.get('Content-Length','0'))
            maximum=DATABASE_IMPORT_LIMIT if path=='/api/import' else JSON_IMPORT_LIMIT
            if not 0<=length<=maximum:return self.send({'error':'저장 파일 크기가 허용 범위를 벗어났습니다. 원본 데이터베이스를 보존해 주세요.'},413)
            prefix=self.rfile.read(min(length,16))
            if path=='/api/import' and prefix==b'SQLite format 3\x00':return self.receive_database(prefix,length)
            if length>JSON_IMPORT_LIMIT:return self.send({'error':'큰 저장 파일은 데이터베이스 저장 형식을 사용해 주세요.'},413)
            raw=prefix+self.rfile.read(length-len(prefix))
            if path=='/api/admin/login':
                token=self.app.authority.login(json.loads(raw or b'{}').get('key'))
                return self.send({'ok':True},cookie='prot_operator='+token+'; HttpOnly; SameSite=Strict; Path=/; Max-Age=28800')
            if path=='/api/admin/logout':
                self.app.authority.logout(self.headers.get('Cookie'))
                return self.send({'ok':True},cookie='prot_operator=; HttpOnly; SameSite=Strict; Path=/; Max-Age=0')
            if path=='/api/import':
                if raw.startswith(b'\x1f\x8b'):
                    with gzip.GzipFile(fileobj=io.BytesIO(raw)) as compressed:raw=compressed.read(JSON_IMPORT_LIMIT+1)
                    if len(raw)>JSON_IMPORT_LIMIT:return self.send({'error':'큰 저장은 데이터베이스 저장 형식으로 불러와 주세요.'},413)
                data=json.loads(raw)
                with self.app.operations:
                    self.app.store.restore(data);self.app.clock.configure({'enabled':False})
                return self.send(self.app.status(True))
            data=json.loads(raw or b'{}')
            if path=='/api/clock':
                with self.app.operations:return self.send(self.app.clock.configure(data))
            if path=='/api/advance':
                provider=data.get('provider','claude');months=data.get('months',1)
                return self.send(self.app.advance(provider,months),202)
            if path=='/api/resume':
                with self.app.operations:
                    j=self.app.store.get_job(data['id'])
                    if j['provider']=='claude' and not self.app.claude.status(True)['loggedIn']:raise ValueError('Claude Code 로그인 후 재개해 주세요.')
                    self.app.runner.start(j);return self.send(j,202)
            if path=='/api/cancel':
                with self.app.operations:
                    active=self.app.store.active();self.app.runner.cancel(data['id'])
                    if active and active['id']==data['id']:self.app.clock.configure({'enabled':False})
                return self.send({'ok':True})
            if path=='/api/player/birth':return self.send(self.app.player_birth(data.get('basis','population')),201)
            if path=='/api/arrive':return self.send(self.app.mutate('arrive',data.get('count',100)))
            if path=='/api/config':return self.send(self.app.mutate('config',data))
            return self.send({'error':'요청을 찾지 못했습니다.'},404)
        except PermissionError as e:self.send({'error':str(e)},403)
        except (ValueError,KeyError,TypeError) as e:self.send({'error':str(e)},400)
        except (BrokenPipeError,ConnectionResetError):pass
        except Exception as e:self.send({'error':'처리 중 오류가 발생했습니다. 기존 저장은 유지됩니다.','detail':type(e).__name__},500)

def main():
    parser=argparse.ArgumentParser();parser.add_argument('--port',type=int,default=8769);parser.add_argument('--db',default=str(ROOT/'state'/'world.sqlite3'));a=parser.parse_args()
    app=App(a.db)
    app.initialize_clock_policy()
    server=ThreadingHTTPServer(('127.0.0.1',a.port),Handler);server.app=app;app.clock.start()
    print(f'프로트 연대기 http://127.0.0.1:{a.port}/',flush=True)
    try:server.serve_forever(poll_interval=.5)
    except KeyboardInterrupt:pass
    finally:app.clock.close();server.server_close()
from childhood import install as install_childhood
