    def set_setting(self,key,value):
        with self.lock,self.connect() as db:db.execute('INSERT INTO operator_settings VALUES(?,?) ON CONFLICT(key) DO UPDATE SET payload=excluded.payload',(key,dumps(value)))

    def active(self):
        with self.connect() as db:
            row=db.execute("SELECT payload FROM jobs WHERE status IN ('queued','running','paused','failed') ORDER BY created DESC LIMIT 1").fetchone()
            return json.loads(row[0]) if row else None

    def get_job(self,jid):
        with self.connect() as db:
            r=db.execute('SELECT payload FROM jobs WHERE id=?',(jid,)).fetchone()
            if not r:raise ValueError('진행 기록을 찾지 못했습니다.')
            return json.loads(r[0])

    def update_job(self,j):
        with self.lock,self.connect() as db:
            row=db.execute('SELECT status FROM jobs WHERE id=?',(j['id'],)).fetchone()
            if row and row[0]=='cancelled' and j['status']!='cancelled':return False
            db.execute('UPDATE jobs SET status=?,payload=? WHERE id=?',(j['status'],dumps(j),j['id']))

    def cancel_job(self,jid):
        with self.lock,self.connect() as db:
            db.execute('BEGIN IMMEDIATE');row=db.execute('SELECT payload FROM jobs WHERE id=?',(jid,)).fetchone()
            if not row:raise ValueError('작업을 찾지 못했습니다.')
            j=json.loads(row[0])
            if j['status'] in ['done','cancelled']:return
            j.update(status='cancelled',message='사용자가 취소했습니다. 확정 전 세계는 보존됩니다.')
            db.execute('UPDATE jobs SET status=?,payload=? WHERE id=?',(j['status'],dumps(j),jid))

    def new_job(self,provider,months):
