            if db.execute("SELECT 1 FROM jobs WHERE status IN ('queued','running','paused','failed')").fetchone():raise ValueError('먼저 진행 중인 작업을 이어가거나 취소해 주세요.')
            w=json.loads(db.execute('SELECT state FROM world WHERE id=1').fetchone()[0]);now=time.time()
            j={'id':uuid.uuid4().hex,'status':'queued','provider':provider,'baseRevision':w['revision'],'months':months,'completedMonths':0,'month':w['month']+1,'totalBatches':0,'doneBatches':0,'currentBatch':0,'actors':0,'message':'같은 날짜의 행동 의도를 준비합니다.','error':None,'startedAt':now,'updatedAt':now}
            db.execute('INSERT INTO jobs VALUES(?,?,?,?,?)',(j['id'],j['status'],provider,dumps(j),now));return j

    def batch(self,jid,month,index):
        with self.connect() as db:
            r=db.execute('SELECT payload FROM batches WHERE job_id=? AND month=? AND batch=?',(jid,month,index)).fetchone();return json.loads(r[0]) if r else None

    def save_batch(self,jid,month,index,record):
        with self.lock,self.connect() as db:
            db.execute('BEGIN IMMEDIATE');j=json.loads(db.execute('SELECT payload FROM jobs WHERE id=?',(jid,)).fetchone()[0])
            if j['status']=='cancelled':raise ValueError('사용자가 취소한 작업입니다.')
            db.execute('INSERT INTO batches VALUES(?,?,?,?)',(jid,month,index,dumps(record)))

    def commit(self,w,expected_revision,job=None):
        validate_world(w)
        with self.lock,self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            revision=db.execute('SELECT revision FROM world WHERE id=1').fetchone()[0]
            if revision!=expected_revision:raise ValueError('세계가 변경돼 오래된 의도를 확정하지 않았습니다.')
            if job:
                saved=json.loads(db.execute('SELECT payload FROM jobs WHERE id=?',(job['id'],)).fetchone()[0])
                if saved['status']=='cancelled':raise ValueError('취소된 결과는 세계에 반영하지 않습니다.')
            self._insert_events(db,w['_events']);state=copy.deepcopy(w);state['_events']=[]
            db.execute('UPDATE world SET revision=?,state=? WHERE id=1',(state['revision'],dumps(state)))
            if job:db.execute('UPDATE jobs SET status=?,payload=? WHERE id=?',(job['status'],dumps(job),job['id']))

    def events(self,person=None,kind=None,offset=0,limit=40):
        clauses=[];params=[]
        if person:clauses.append('EXISTS(SELECT 1 FROM person_events p WHERE p.event_id=e.id AND p.person_id=?)');params.append(person)
        if kind=='story':clauses.append("e.kind NOT IN ('action','income','income_year','family_support','regional_budget','prot_market','year_closed','endowment_paid')")
        elif kind:clauses.append('e.kind=?');params.append(kind)
        where=' WHERE '+' AND '.join(clauses) if clauses else ''
        with self.connect() as db:
            total=db.execute('SELECT COUNT(*) FROM events e'+where,params).fetchone()[0]
            rows=db.execute('SELECT payload FROM events e'+where+' ORDER BY month DESC,id DESC LIMIT ? OFFSET ?',params+[min(100,max(1,limit)),max(0,offset)]).fetchall()
            return {'total':total,'items':[json.loads(r[0]) for r in rows]}

    def audit(self,jid=None):
        with self.connect() as db:
            q='SELECT payload FROM batches'+(' WHERE job_id=?' if jid else '')+' ORDER BY month DESC,batch'
            return [json.loads(r[0]) for r in db.execute(q,(jid,) if jid else ()).fetchall()]

    def export(self):
        with self.lock,self.connect() as db:
            return {'format':'shield-prot-save-v3','state':json.loads(db.execute('SELECT state FROM world WHERE id=1').fetchone()[0]),'events':[json.loads(r[0]) for r in db.execute('SELECT payload FROM events ORDER BY month,id')],'jobs':[json.loads(r[0]) for r in db.execute('SELECT payload FROM jobs ORDER BY created')],'batches':[{'jobId':r['job_id'],'month':r['month'],'index':r['batch'],'payload':json.loads(r['payload'])} for r in db.execute('SELECT * FROM batches ORDER BY month,batch')]}

    def backup_database(self,destination):
        with self.lock,self.connect() as src:
            dest=sqlite3.connect(destination)
            try:src.backup(dest)
            finally:dest.close()

    def restore_database(self,path):
        """Stream trusted-schema rows into our own schema; never import SQL or triggers."""
        src=sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True);src.row_factory=sqlite3.Row
        try:
            src.execute('PRAGMA trusted_schema=OFF')
            if src.execute('PRAGMA quick_check').fetchone()[0]!='ok':raise ValueError('저장 데이터베이스의 무결성을 확인하지 못했습니다.')
            tables={r['name']:r['type'] for r in src.execute("SELECT name,type FROM sqlite_master WHERE type IN ('table','trigger','view')")}
            allowed={'world','events','person_events','jobs','batches','operator_settings'}
            if set(tables)-allowed or any(v!='table' for v in tables.values()) or not allowed.difference({'operator_settings'})<=tables.keys():raise ValueError('이 프로트 저장 파일의 표 구조가 아닙니다.')
            columns={'world':['id','revision','state'],'events':['id','month','kind','payload'],'person_events':['person_id','event_id','month'],'jobs':['id','status','provider','payload','created'],'batches':['job_id','month','batch','payload']}
            for table,expected in columns.items():
                info=list(src.execute('PRAGMA table_info('+table+')'))
                if [r['name'] for r in info]!=expected:raise ValueError('저장 표의 열 구성이 일치하지 않습니다.')
                if table=='events' and not any(r['name']=='id' and r['pk']==1 for r in info):raise ValueError('원본 사건의 고유 ID 제약이 없습니다.')
            rows=src.execute('SELECT * FROM world').fetchall()
            if len(rows)!=1 or rows[0]['id']!=1:raise ValueError('세계 원본을 찾지 못했습니다.')
            state=json.loads(rows[0]['state'])
            if rows[0]['revision']!=state['revision']:raise ValueError('세계 변경 번호가 일치하지 않습니다.')
            def events():
                for r in src.execute('SELECT * FROM events'):
                    e=json.loads(r['payload'])
                    if any(e[k]!=r[k] for k in ['id','month','kind']):raise ValueError('사건 원본과 색인 값이 일치하지 않습니다.')
                    yield e
            def jobs():
                for r in src.execute('SELECT * FROM jobs'):
                    j=json.loads(r['payload'])
                    if any(j[k]!=r[k] for k in ['id','status','provider']):raise ValueError('AI 작업 원본과 색인 값이 일치하지 않습니다.')
                    yield j
            def batches():
                for r in src.execute('SELECT * FROM batches'):yield {'jobId':r['job_id'],'month':r['month'],'index':r['batch'],'payload':json.loads(r['payload'])}
            validate_archive(state,events(),jobs(),batches(),unique_events=False)
            with self.lock:
                if self.active():raise ValueError('진행 작업을 마치거나 취소한 뒤 불러와 주세요.')
                backup=self.path.parent/'backups';backup.mkdir(exist_ok=True);self.backup_database(backup/f'world-before-import-{time.time_ns()}.sqlite3')
                with self.connect() as db:
                    db.execute('BEGIN IMMEDIATE')
                    for table in ['person_events','events','batches','jobs']:db.execute('DELETE FROM '+table)
                    state['_events']=[];db.execute('UPDATE world SET revision=?,state=? WHERE id=1',(state['revision'],dumps(state)))
                    for e in events():self._insert_events(db,[e])
                    for j in jobs():
                        if j['status'] in ACTIVE:j.update(status='cancelled',message='불러온 이전 작업. 필요하면 새로 진행하세요.')
                        db.execute('INSERT INTO jobs VALUES(?,?,?,?,?)',(j['id'],j['status'],j['provider'],dumps(j),j.get('startedAt',0)))
                    for b in batches():db.execute('INSERT INTO batches VALUES(?,?,?,?)',(b['jobId'],b['month'],b['index'],dumps(b['payload'])))
