        except sqlite3.DatabaseError as e:raise ValueError('이 프로토타입의 정상 저장 데이터베이스가 아닙니다.') from e
        finally:src.close()

    def restore(self,data):
        if data.get('format')!='shield-prot-save-v3':raise ValueError('이 프로토타입의 세계 저장 파일이 아닙니다.')
        state=data.get('state',{});validate_archive(state,data.get('events',[]),data.get('jobs',[]),data.get('batches',[]))
        if not isinstance(data.get('events'),list):raise ValueError('개인 기록이 포함된 저장 파일이 필요합니다.')
        event_ids=[e['id'] for e in data['events']]
        if len(event_ids)!=len(set(event_ids)):raise ValueError('저장 기록 ID가 중복됩니다.')
        with self.lock:
            if self.active():raise ValueError('진행 작업을 마치거나 취소한 뒤 불러와 주세요.')
            backup=self.path.parent/'backups';backup.mkdir(exist_ok=True)
