"""Local operator authority. Keys never enter game saves or source packages."""
import hmac,os,secrets,threading,time
from http.cookies import SimpleCookie
from pathlib import Path

class Authority:
    def __init__(self,folder):
        self.folder=Path(folder);self.folder.mkdir(parents=True,exist_ok=True)
        path=self.folder/'admin.key'
        try:
            fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL,0o600)
            with os.fdopen(fd,'w',encoding='ascii') as f:f.write(secrets.token_urlsafe(32))
        except FileExistsError:pass
        self.key=path.read_text(encoding='ascii').strip()
        if len(self.key)<32:raise ValueError('관리자 키 파일을 확인해 주세요.')
        self.sessions={};self.lock=threading.Lock()

    def login(self,key):
        if not isinstance(key,str) or not hmac.compare_digest(key,self.key):raise PermissionError('관리자 실행 파일로 접속해 주세요.')
        with self.lock:
            now=time.time();self.sessions={k:v for k,v in self.sessions.items() if v>now}
            if len(self.sessions)>=64:self.sessions.pop(next(iter(self.sessions)))
            token=secrets.token_urlsafe(32);self.sessions[token]=now+8*3600;return token

    def authenticated(self,header):
        try:
            cookies=SimpleCookie();cookies.load(header or '')
            token=cookies['prot_operator'].value
        except (KeyError,ValueError):return False
        with self.lock:return self.sessions.get(token,0)>time.time()

    def logout(self,header):
        try:
            cookies=SimpleCookie();cookies.load(header or '');token=cookies['prot_operator'].value
        except (KeyError,ValueError):return
        with self.lock:self.sessions.pop(token,None)

