"""Single local world clock, independent of browser visits and player creation."""
import threading,time

DEFAULT={'enabled':False,'provider':'rules','intervalSeconds':600,'nextRun':None,'lastJob':None,'error':None}

class WorldClock:
    def __init__(self,app):
        self.app=app;self.stop=threading.Event();self.thread=None
        self.config={**DEFAULT,**app.store.setting('worldClock',{})}

    def status(self):return dict(self.config)

    def save(self):self.app.store.set_setting('worldClock',self.config)

    def configure(self,data):
        enabled=data.get('enabled');provider=data.get('provider',self.config['provider']);interval=data.get('intervalSeconds',self.config['intervalSeconds'])
        if not isinstance(enabled,bool) or provider!='rules' or type(interval) is not int or not 10<=interval<=86400:raise ValueError('자동 시계는 규칙 AI로 진행합니다. Claude는 관리자 수동 요청으로만 호출합니다. 간격은 10초~24시간입니다.')
        active=self.app.store.active()
        self.config.update(enabled=enabled,provider=provider,intervalSeconds=interval,nextRun=time.time()+interval if enabled else None,lastJob=active['id'] if enabled and active else None,error=None)
        self.save();return self.status()

    def tick(self,now=None):
        now=time.time() if now is None else now
        with self.app.operations:
            c=self.config
            if not c['enabled']:return
            active=self.app.store.active()
            if active:
                if active['status'] in ['running','queued'] and not(self.app.runner.thread and self.app.runner.thread.is_alive()):
                    active.update(status='failed',error=self.app.runner.last_error or '행동 생성 실행이 중단됐습니다.',message='완료한 묶음부터 재개해 주세요.');self.app.store.update_job(active)
                if active['status'] in ['failed','paused']:
                    c.update(enabled=False,nextRun=None,error='진행이 중단돼 자동 시계를 멈췄습니다. 관리자가 저장된 묶음부터 재개해 주세요.');self.save()
                return
            if self.app.runner.thread and self.app.runner.thread.is_alive():return
            if c['lastJob']:
                completed=self.app.store.get_job(c['lastJob'])
                if completed['status']=='done':
                    c.update(lastJob=None,nextRun=now+c['intervalSeconds']);self.save();return
                if completed['status']=='cancelled':
                    c.update(enabled=False,lastJob=None,nextRun=None,error='작업 취소로 자동 진행을 멈췄습니다.');self.save();return
            if c['nextRun'] is None or now<c['nextRun']:return
            try:
                job=self.app.advance(c['provider'],1)
                c.update(lastJob=job['id'],nextRun=None,error=None);self.save()
            except Exception as e:
                c.update(enabled=False,nextRun=None,error=str(e));self.save()

    def start(self):
        if self.thread and self.thread.is_alive():return
        def run():
            while not self.stop.wait(1):
                try:self.tick()
                except Exception:
                    with self.app.operations:
                        self.config.update(enabled=False,nextRun=None,error='자동 진행 오류로 세계 시계를 멈췄습니다. 기존 기록은 보존됩니다.');self.save()
