 'play':{'name':'놀이와 기초 돌봄','skill':None,'job':None,'description':'어릴 때는 안전하게 먹고 쉬며 자랍니다.'},
 'letters':{'name':'문자와 장부','skill':'read','job':'clerk','description':'공부 세 달마다 문서 판독 숙련 1, 아동기 최대 30.'},
 'herbs':{'name':'약초와 돌봄','skill':'aid','job':'healer','description':'공부 세 달마다 응급처치 숙련 1, 아동기 최대 30.'},
 'shield':{'name':'방패와 몸 익히기','skill':'brace','job':'guard','description':'공부 세 달마다 방패막기 숙련 1, 아동기 최대 30.'}}
