def year_events(store,pid,month):
    """Read this calendar year's personal stories, without a last-80 truncation."""
    first=month//12*12;rows=[];offset=0
    while True:
        page=store.events(person=pid,kind='story',offset=offset,limit=100)
        rows.extend(e for e in page['items'] if first<=e['month']<=month)
        offset+=len(page['items'])
        if not page['items'] or offset>=page['total'] or page['items'][-1]['month']<first:return rows

def campaign(w):
    c=w.get('childhood')
    if not c:return None
    if c.get('version')!=1 or c.get('person') not in w['people']:raise ValueError('아동기 저장 연결을 확인해 주세요.')
    if (w.get('player') or {}).get('id')!=c['person']:raise ValueError('내 인물과 아동기 기록이 일치하지 않습니다.')
    if c.get('origin') not in ['family','orphan'] or c.get('phase') not in ['choice','ready','growing','naming','complete','ended']:raise ValueError('아동기 단계가 올바르지 않습니다.')
    if c.get('birthMonth')!=w['people'][c['person']]['birthMonth'] or type(c.get('targetMonth')) is not int:raise ValueError('아동기 출생 시점이 일치하지 않습니다.')
    if not isinstance(c.get('decisions'),list) or not all(isinstance(c.get(k),dict) and set(c[k])<=COURSES.keys() and all(type(v) is int and v>=0 for v in c[k].values()) for k in ['studyMonths','learned']):raise ValueError('아동기 배움 기록이 올바르지 않습니다.')
    if type(c.get('supportTotal')) is not int or c['supportTotal']<0 or c.get('adultName') is not None and not isinstance(c['adultName'],str):raise ValueError('아동기 후원·이름 기록이 올바르지 않습니다.')
    choice=c.get('choice')
    if choice is not None and (not isinstance(choice,dict) or choice.get('learning') not in COURSES or choice.get('support') not in SUPPORTS or choice.get('sponsor') is not None and choice['sponsor'] not in w['people']):raise ValueError('아동기 선택 기록이 올바르지 않습니다.')
    return c

def mentors(w,p,learning):
    job=COURSES[learning]['job']
    rows=[q for q in world.living(w) if q['id']!=p['id'] and q.get('town')==p.get('town') and world.age(q,w['month'])>=25 and q['cash']>500 and q['temperament']['돌봄']>=3]
    rows.sort(key=lambda q:(q['job']!=job,-q['temperament']['돌봄'],-q['cash'],q['id']))
    return rows[:3]

def initial_roll(w,origin,seed):
    """The prototype explicitly fixes Prot and origin; remaining traits are sampled."""
    rng=random.Random(seed);shares=world.race_share(w,'KARTE');race=rng.choices(list(shares),list(shares.values()))[0]
    sex=rng.choice(['F','M']);probability=shares[race]*.5
    return {'seed':seed,'basis':'prot-childhood','nation':'KARTE','region':'PROT','town':'prot','status':'common','race':race,'sex':sex,'orphan':origin=='orphan','route':'unknown' if origin=='orphan' else None,'wealth':'poor' if origin=='orphan' else 'middle','steps':[{'step':'체험 범위','value':'prot','label':'프로트·출신 직접 선택 체험','probability':1},{'step':'종족','value':race,'label':race,'probability':shares[race]},{'step':'성별','value':sex,'label':sex,'probability':.5}], 'probability':probability,'oneIn':round(1/probability)}

def after_month(w):
    c=campaign(w);p=w['people'][c['person']];age=world.age(p,w['month'])
    if not p['alive']:
        c.update(phase='ended',endedMonth=w['month']);return
    choice=c['choice'];course=COURSES[choice['learning']]
    if age>=6 and age<16 and course['skill'] and p['health']>=50:
        k=choice['learning'];c['studyMonths'][k]=c['studyMonths'].get(k,0)+1
        if c['studyMonths'][k]%3==0 and c['learned'].get(k,0)<30:
            p['skills'][course['skill']]+=1;c['learned'][k]=c['learned'].get(k,0)+1
            world.emit(w,'childhood_learning',[p['id']],f"{p['name']}이 {course['name']}을 익혔다.",skill=course['skill'],gain=1,learning=k)
    donor=w['people'].get(choice.get('sponsor'))
