        if choice['support']=='community' and not p.get('orphanage'):amount=0
        if amount:
            donor['cash']-=amount;oid=p.get('orphanage')
            if choice['support']=='community' and oid in w.get('orphanages',{}):w['orphanages'][oid]['funds']+=amount;destination='구호원 공동 기금'
            else:p['trust']+=amount;destination='본인 보호 재산'
            c['supportTotal']+=amount
            world.emit(w,'childhood_support',[p['id'],donor['id']],f"{donor['name']}이 {p['name']}의 {destination}에 후원했다.",amount=amount,sponsor=donor['id'],recipient=p['id'],destination=destination)
