class ChildhoodRunner(Runner):
    def run(self,jid):
        if not self.store.get_job(jid).get('childhood'):return super().run(jid)
        j=self.store.get_job(jid)
        try:
            if j['completedMonths']>=j['months']:
                if self.store.load()['revision']!=j['baseRevision']+j['months']:raise ValueError('세계와 완료 기록을 확인해 주세요.')
                self.update(j,status='done',error=None);return
            self.update(j,status='running',error=None)
            while j['completedMonths']<j['months']:
                w=self.store.load();c=campaign(w);pid=j['childhood']['person'];p=w['people'][pid]
                if not c or c['person']!=pid:raise ValueError('이 작업의 내 인물 연결이 바뀌었습니다.')
                expected=j['baseRevision']+j['completedMonths']
                if w['revision']!=expected:raise ValueError('세계가 변경돼 오래된 선택으로 진행하지 않습니다.')
                done=0;events=[];stopped=False
                # Only this worker owns the loaded JSON world. If a month fails or is
                # cancelled, discard this uncommitted year and retry from the saved DB.
                while done<12 and j['completedMonths']+done<j['months']:
                    c=campaign(w);p=w['people'][pid]
                    actors=sorted(world.living(w),key=lambda q:q['id']);chunks=[actors[i:i+100] for i in range(0,len(actors),100)];intents=[]
                    self.update(j,month=w['month']+1,computedMonths=j['completedMonths']+done,totalBatches=len(chunks),actors=len(actors),doneBatches=0,message=f"{world.age(p,w['month'])}세 · 저장 {j['completedMonths']}/{j['months']}개월 · 다음 달을 계산합니다.")
                    for index,chunk in enumerate(chunks):
                        if self.stop.is_set():raise ValueError('진행이 취소됐습니다.')
                        # Reuse persisted plans from jobs made by an older runner.
                        # New rules-only plans are deterministic and need no batch writes.
                        record=self.store.batch(jid,j['month'],index)
                        if record:plans=record['intents']
                        else:
                            plans=world.utility_intents(w,chunk)
                            for i in plans:
                                if i['id']==pid:i.update(a='study',why=COURSES[c['choice']['learning']]['name']+'을 선택한 아동기');i.pop('n',None)
                        world.validate_intents(chunk,plans);intents.extend(plans)
                    self.update(j,doneBatches=len(chunks))
                    new_job=None
                    # Only this person's automatic naming is deferred; NPCs keep normal rules.
                    if world.age(p,w['month']+1)>=16:
                        child=w['people'][pid];child['needsNaming']=False
                        job=COURSES[c['choice']['learning']]['job'] or 'clerk'
                        if not child['job']:child['job']=job;new_job=job
                    result=world.resolve(w,intents,'rules',inplace=True)
                    if new_job and result['people'][pid]['alive']:
                        child=result['people'][pid]
                        if result.get('schema',3)>=20 and any(q['job']=='teacher' and q.get('town')==child.get('town') for q in world.living(result)):child['skills'][world.SKILLS[new_job][0]]+=10
                        world.emit(result,'apprenticeship',[pid],child['name']+'이 선택한 배움을 따라 생업에 첫발을 내디뎠다.',job=new_job,source='childhood')
                    after_month(result)
                    events.extend(result['_events']);w=result;done+=1
                    stopped=w['childhood']['phase'] in ['naming','ended']
                    if stopped or w['month']>=c['targetMonth']:break
                if self.stop.is_set():raise ValueError('진행이 취소됐습니다.')
                w['_events']=events;next_job=copy.deepcopy(j);next_job['completedMonths']+=done;next_job['computedMonths']=next_job['completedMonths']
                if stopped:next_job['months']=next_job['completedMonths']
                next_job.update(status='done' if next_job['completedMonths']==next_job['months'] else 'running',updatedAt=time.time(),message='이번 성장 구간과 모든 인물 기록을 저장했습니다.')
                self.store.commit(w,expected,next_job);j=next_job
            w=self.store.load()
            if campaign(w) and w['childhood']['phase']=='growing':
                rev=w['revision'];w['childhood']['phase']='choice';w['revision']+=1;self.store.commit(w,rev)
        except Exception as e:
            self.last_error=str(e)
            try:
                current=self.store.get_job(jid)
                if current['status']!='cancelled':j.update(status='failed',computedMonths=j['completedMonths'],error=str(e),message='마지막 저장 지점은 보존했습니다. 저장하지 못한 구간은 이어 하기로 다시 계산합니다.');self.store.update_job(j)
            except Exception:pass
        finally:
            with self.lock:
                if self.current_job==jid:self.current_job=None

class Childhood:
    def __init__(self,app):self.app=app;self.store=app.store
    def owner(self,header,admin=False):
        if admin:return True
        from http.cookies import SimpleCookie
        try:jar=SimpleCookie();jar.load(header or '');token=jar[COOKIE].value
        except (KeyError,ValueError):return False
        saved=self.store.setting('childhoodOwner',{})
        c=campaign(self.store.load())
        return bool(c and saved.get('person')==c['person'] and hmac.compare_digest(saved.get('hash',''),hashlib.sha256(token.encode()).hexdigest()))
    def status(self,owned=False):
        w=self.store.load();c=campaign(w);j=self.store.active();p=w['people'][c['person']] if c else None
        summary=world.summary(w)
        if p and not p['alive']:phase='ended'
        elif c and j is None and c['phase']=='growing':
            # A completed/cancelled annual job is recoverable even after browser/server restart.
            phase='naming' if world.age(p,w['month'])>=16 else 'choice' if p['alive'] else 'ended'
        else:phase=c['phase'] if c else 'start'
        person=world.public_person(w,p) if p else None
        if person:
            person['jobName']=world.JOB_NAMES.get(p['job'],'생업 없음' if not p['job'] else '새로운 생업')
            person['familyChildren']=sorted({*person['children'],*(q['id'] for q in world.children(w,p['id'],True))})
        relatives={*p['biologicalParents'],*p['legalParents'],p.get('guardian'),p.get('spouse'),*person['familyChildren']} if p else set()
        names={pid:q['name'] for pid,q in w['people'].items() if pid in relatives}
        choices=list(COURSES) if p and world.age(p,w['month'])>=6 else ['play']
        bycourse={course:[{k:q[k] for k in ['id','name','race','job']} for q in mentors(w,p,course)] for course in choices} if p and world.age(p,w['month'])<16 else {}
        settling=bool(j is None and self.app.runner.thread and self.app.runner.thread.is_alive())
        return {'world':{k:summary[k] for k in ['id','month','revision','registered','alive','born','died']},'campaign':{**c,'phase':phase} if c else None,'person':person,'names':names,'courses':{k:COURSES[k] for k in choices if k!='play' or len(choices)==1},'supports':SUPPORTS,'mentorsByCourse':bycourse,'history':self.store.events(person=p['id'],limit=80)['items'] if p else [],'yearEvents':year_events(self.store,p['id'],w['month']) if phase=='complete' else [],'activeJob':j,'settling':settling,'owned':owned,'automatic':self.app.clock.status()}
    def _idle(self,revision):
