        if not 1<=len(name)<=16 or not all(x.isalnum() or x in ' ·-' for x in name) or not any(x.isalnum() for x in name):raise ValueError('이름은 한글·글자·숫자·공백으로 1~16자 입력해 주세요.')
        with self.app.operations,self.store.lock:
