            old=p['name'];p.update(name=name,needsNaming=False,preferredName=None);p['nameHistory'].append({'month':w['month'],'name':name,'old':old,'kind':'플레이어가 직접 정한 성년 이름'})
            world.emit(w,'naming',[p['id']],f"{old}이 자신의 이름을 {name}으로 선언했다. 같은 ID와 가족 기록을 이어간다.",oldName=old,newName=name,source='player')
            world.emit(w,'childhood_completed',[p['id']],name+'의 0~16세 아동기를 마쳤다. 배움·후원·혈육과 이름 이력은 같은 세계에 남는다.',learning=dict(c['learned']),support=c['supportTotal'])
            c.update(adultName=name,phase='complete',completedMonth=w['month']);w['revision']+=1;self.store.commit(w,revision)

