"""After the player's death (DEATH_CHOICE_DESIGN_v1): death report, heir candidates, spectator fast-forward, period report.
Claude-owned module. Hooks into the server like childhood.py does; never touches w['childhood']."""
import copy,json,time
from urllib.parse import parse_qs,urlsplit
import world

SPECTATE_YEARS=[5,10,25,50,100]
SAVE_EVERY=12   # D6: a spectated year is computed in memory and saved once
PUBLIC_JOB=['id','status','months','completedMonths','month','message','error','updatedAt']

def public_job(j):
    """Codex /play reads fromMonth and toMonth; toMonth is the last month actually saved."""
    if not j:return None
    s=j.get('spectate') or {}
    return {**{k:j.get(k) for k in PUBLIC_JOB},'spectate':{k:s.get(k) for k in ['years','from','to','saveEvery']},'fromMonth':s.get('from'),'toMonth':s.get('from',0)+j.get('completedMonths',0)}

def spectate_runner(base):
    """The app's runner class with one more job type. Other jobs keep the base behaviour (one job at a time)."""
    class SpectateRunner(base):
        def run(self,jid):
            j=self.store.get_job(jid)
            if not j.get('spectate'):return super().run(jid)
            try:
                self.update(j,status='running',error=None)
                while j['completedMonths']<j['months']:
                    w=self.store.load();expected=j['baseRevision']+j['completedMonths']
                    if w['revision']!=expected:raise ValueError('세계가 바뀌어 관전을 이어 가지 않습니다.')
                    pl=w.get('player')
                    if pl and w['people'][pl['id']]['alive']:raise ValueError('내 인물이 살아 있어 관전을 멈췄습니다.')
                    n=min(SAVE_EVERY,j['months']-j['completedMonths']);events=[]
                    for k in range(n):
                        m=w['month']+1
                        self.update(j,month=m,message=f"{m//12+1}년 {m%12+1}월 · {j['completedMonths']+k+1:,}/{j['months']:,}개월 관전 중")
                        w=world.resolve(w,world.utility_intents(w,world.living(w)),'rules',inplace=True);events+=w['_events']   # the loaded copy is never reused
                    w['_events']=events;nxt=copy.deepcopy(j);nxt['completedMonths']+=n
                    nxt.update(status='done' if nxt['completedMonths']==nxt['months'] else 'running',message=f"{nxt['completedMonths']//12}년치 세계 기록을 저장했습니다.",updatedAt=time.time())
                    self.store.commit(w,expected,nxt);j=nxt
            except Exception as e:
                self.last_error=str(e)
                try:
                    if self.store.get_job(jid)['status']!='cancelled':
                        j.update(status='failed',error=str(e),message='저장한 해까지는 세계에 남았습니다. 이어 하기로 재개할 수 있습니다.',updatedAt=time.time());self.store.update_job(j)
                except Exception:pass
            finally:
                with self.lock:
                    if self.current_job==jid:self.current_job=None
    return SpectateRunner

class Afterlife:
    def __init__(self,app):self.app=app;self.store=app.store
    def spectate_job(self):
        with self.store.connect() as db:
            for (payload,) in db.execute('SELECT payload FROM jobs ORDER BY created DESC LIMIT 50'):
                j=json.loads(payload)
                if j.get('spectate'):return j
        return None
    def status(self,owned=False):
        with self.store.lock:   # one consistent snapshot of world and jobs
            w=self.store.load();busy=self.store.active() is not None;job=self.spectate_job()
        pl=w.get('player');p=w['people'].get(pl['id']) if pl else None;alive=bool(p and p['alive'])
        heirs=world.heir_candidates(w) if p and not alive else []
        idle='진행 중인 작업을 먼저 끝내거나 취소해 주세요.'
        reborn=(False,'내 인물이 아직 살아 있습니다.') if alive else (False,idle) if busy else (True,None)
        heir=(False,'이어 살 전생 인물이 없습니다.') if not p else reborn if not reborn[0] else (False,'16세 미만의 살아 있는 직계 자손이 없습니다.') if not heirs else (True,None)
        opt=lambda x:{'ok':x[0],'reason':x[1]}
        return {'world':{'month':w['month'],'revision':w['revision'],'season':w['season']},'player':pl,'alive':alive,'owned':owned,
                'report':world.life_report(w,p['id']) if p and not alive else None,'heirs':heirs,
                'options':{'reborn':opt(reborn),'heir':opt(heir),'spectate':{**opt(reborn),'choices':SPECTATE_YEARS+['season']}},
                'spectate':public_job(job)}
    def spectate(self,years,revision):
        with self.app.operations,self.store.lock:
            w=self.store.load()
            if type(revision) is not int or revision!=w['revision']:raise ValueError('세계 상태가 바뀌었습니다. 화면을 새로 확인한 뒤 골라 주세요.')
            pl=w.get('player')
            if pl and w['people'][pl['id']]['alive']:raise ValueError('내 인물이 살아 있는 동안에는 관전 빨리감기를 할 수 없습니다.')
            if years=='season':months=max(1,w['season']['months']-w['month'])
            elif type(years) is int and years in SPECTATE_YEARS:months=12*years
            else:raise ValueError('관전 기간은 5·10·25·50·100년 또는 다음 시즌 결산까지 중에서 골라 주세요.')
            runner=self.app.runner
            with runner.lock:   # a cancelled run may still be finishing its month; never leave a queued job nobody runs
                if runner.thread and runner.thread.is_alive():raise ValueError('이전 계산을 정리하는 중입니다. 잠시 뒤 다시 골라 주세요.')
            j=self.store.new_job('rules',months)
            j.update(spectate={'years':years,'from':w['month'],'to':w['month']+months,'saveEvery':SAVE_EVERY,'start':world.country_lines(w)},message='관전 빨리감기를 준비합니다.')
            self.store.update_job(j)
            try:runner.start(j)
            except Exception:
                self.store.cancel_job(j['id']);raise
            return public_job(self.store.get_job(j['id']))
    def cancel(self):
        j=self.store.active()
        if not j or not j.get('spectate'):raise ValueError('진행 중인 관전이 없습니다.')
        self.app.runner.cancel(j['id']);return public_job(self.store.get_job(j['id']))
    def resume(self):
        with self.app.operations:
            j=self.store.active()
            if not j or not j.get('spectate'):raise ValueError('이어 갈 관전이 없습니다.')
            self.app.runner.start(j);return public_job(self.store.get_job(j['id']))
    def chronicle(self,start,end=None):
        w=self.store.load();end=w['month'] if end is None else end
        if not (type(start) is int and type(end) is int and 0<=start<=end<=w['month']):raise ValueError('기간은 0개월부터 지금 달 사이로 골라 주세요.')
        kinds=world.CHRONICLE_KINDS;q='SELECT payload FROM events WHERE month BETWEEN ? AND ? AND kind IN ('+','.join('?'*len(kinds))+') ORDER BY month DESC,id DESC LIMIT 2000'
        with self.store.connect() as db:events=[json.loads(r[0]) for r in db.execute(q,(start,end,*kinds))]
        return world.chronicle(w,events,start,end)
    def period(self,start,end):
        w=self.store.load()
        if not (type(start) is int and type(end) is int and 0<=start<=end<=w['month']):raise ValueError('기간은 0개월부터 지금 달 사이로 골라 주세요.')
        kinds=world.PERIOD_KINDS;q='SELECT payload FROM events WHERE month BETWEEN ? AND ? AND kind IN ('+','.join('?'*len(kinds))+') ORDER BY month,id'
        with self.store.connect() as db:events=[json.loads(r[0]) for r in db.execute(q,(start,end,*kinds))]
        j=self.spectate_job();origin=(j['spectate'].get('start') if j and j['spectate']['from']==start else None)
        return world.period_report(w,events,start,end,origin)

def install(App,Handler):
    """One server hook, installed after childhood's, so the spectator runner wraps the childhood runner."""
    original_init=App.__init__
    def init(app,*args,**kwargs):
        original_init(app,*args,**kwargs)
        app.runner=spectate_runner(type(app.runner))(app.store,app.claude);app.afterlife=Afterlife(app)
    App.__init__=init
    get,post=Handler.do_GET,Handler.do_POST
    def request_ok(h):
        host=h.headers.get('Host','');origin=h.headers.get('Origin')
        if host not in [f'127.0.0.1:{h.server.server_port}',f'localhost:{h.server.server_port}'] or origin and origin!='http://'+host:raise PermissionError('이 컴퓨터의 플레이 화면에서 요청해 주세요.')
    def owned(h):
        cookie=h.headers.get('Cookie');admin=h.app.authority.authenticated(cookie)
        return admin or (hasattr(h.app,'childhood') and h.app.childhood.owner(cookie,admin))
    def after_get(h):
        parts=urlsplit(h.path)
        if parts.path not in ['/api/afterlife','/api/afterlife/period','/api/chronicle']:return get(h)
        try:
            request_ok(h);service=h.app.afterlife
            if parts.path=='/api/afterlife':return h.send(service.status(owned(h)))
            q=parse_qs(parts.query);num=lambda k:int(q[k][0]) if k in q and q[k][0].lstrip('-').isdigit() else None
            if parts.path=='/api/chronicle':return h.send(service.chronicle(num('from') or 0,num('to')))   # L2: read-only, open to anyone on this computer
            return h.send(service.period(num('from'),num('to')))
        except PermissionError as e:return h.send({'error':str(e)},403)
        except (ValueError,KeyError,TypeError) as e:return h.send({'error':str(e)},400)
    def after_post(h):
        path=urlsplit(h.path).path
        if not path.startswith('/api/afterlife/'):return post(h)
        try:
            request_ok(h);length=int(h.headers.get('Content-Length','0'))
            if not 0<=length<=4096:raise ValueError('요청이 너무 큽니다.')
            data=json.loads(h.rfile.read(length) or b'{}')
            if not isinstance(data,dict):raise ValueError('요청 내용을 다시 확인해 주세요.')
            if not owned(h):raise PermissionError('이 삶을 시작한 브라우저에서 이어가거나 관리자 인증을 해 주세요.')
            service=h.app.afterlife
            if path=='/api/afterlife/spectate':return h.send(service.spectate(data.get('years'),data.get('revision')),202)
