"""Adult play after the 16th-birthday naming (ADULT_BRANCH_DESIGN_v1 A1~A9, contract CLAUDE_HANDOFF_TO_CODEX.txt [13]).
Claude-owned module. Hooks into the server like childhood.py and afterlife.py; never touches w['childhood']."""
import copy,json,time
from urllib.parse import urlsplit
import world

ADVANCE_MONTHS=(1,12,60)   # A5: next month, next year, five years (only with every branch on auto)
NEXT_LIMIT=360   # F5 'next': run until a branch or death, at most 30 years per press
SAVE_EVERY=12   # months computed in memory between saves
PUBLIC_JOB=['id','status','months','completedMonths','computedMonths','untilBranch','month','message','error','updatedAt']   # computedMonths: months finished in memory, saved at the year's end

def public_job(j):return {k:j.get(k) for k in PUBLIC_JOB} if j else None

def phase(w):
    pl=w.get('player');p=w['people'].get(pl['id']) if pl else None
    if not p:return 'none',None
    if not p['alive']:return 'dead',p
    c=w.get('childhood') or {}
    if world.age(p,w['month'])<16 or (c.get('person')==p['id'] and c.get('phase')!='complete'):return 'child',p
    return 'adult',p

def adult_runner(base):
    """The app's runner class with one more job type: the player's adult months, stopping at branches (A1)."""
    class AdultRunner(base):
        def run(self,jid):
            j=self.store.get_job(jid)
            if not j.get('adult'):return super().run(jid)
            try:
                self.update(j,status='running',error=None)
                while j['completedMonths']<j['months']:
                    w=self.store.load();expected=j['expect']
                    if w['revision']!=expected:raise ValueError('세계가 바뀌어 이 진행을 이어 가지 않습니다.')
                    ph,p=phase(w)
                    if ph!='adult' or p['id']!=j['adult']['person']:raise ValueError('내 인물이 바뀌어 진행을 멈췄습니다.')
                    done=0;events=[];dead=False
                    # Up to a year is computed in memory and saved once (saving was most of the wait); a branch or a death saves at once.
                    while j['completedMonths']+done<j['months'] and done<SAVE_EVERY:
                        m=w['month']+1;self.update(j,month=m,computedMonths=j['completedMonths']+done,message=f"{m//12+1}년 {m%12+1}월 · {j['completedMonths']+done+1}/{j['months']}개월")
                        try:result=world.resolve(w,world.utility_intents(w,world.living(w)),'rules')   # a copy: w stays the last finished month
                        except world.BranchPending as e:   # keep the finished months, let the branch wait at this month
                            w['player']['pending']=e.branch;w['revision']+=1;w['_events']=events
                            nxt=copy.deepcopy(j);nxt['completedMonths']+=done;nxt['computedMonths']=nxt['completedMonths']
                            nxt.update(status='waiting',expect=w['revision'],month=m,message=f"갈림길: {e.branch['title']} — 고르면 같은 달부터 이어 갑니다.",updatedAt=time.time())
                            self.store.commit(w,expected,nxt);return
                        events+=result['_events'];w=result;done+=1
                        if not w['people'][p['id']]['alive']:dead=True;break
                    w['_events']=events;nxt=copy.deepcopy(j);nxt['completedMonths']+=done;nxt['computedMonths']=nxt['completedMonths'];nxt['expect']=w['revision']
                    if dead:nxt['months']=nxt['completedMonths']
                    quiet=j.get('untilBranch') and nxt['completedMonths']>=NEXT_LIMIT
                    nxt.update(status='done' if nxt['completedMonths']==nxt['months'] else 'running',message='내 인물이 세상을 떠났습니다.' if dead else f"{NEXT_LIMIT//12}년 동안 갈림길이 없었습니다. 계속하려면 다시 눌러 주세요." if quiet else '선택한 기간을 마쳤습니다.' if nxt['completedMonths']==nxt['months'] else f"{done}개월을 저장했습니다.",updatedAt=time.time())
                    self.store.commit(w,expected,nxt);j=nxt
            except Exception as e:
                self.last_error=str(e)
                try:
                    if self.store.get_job(jid)['status']!='cancelled':j.update(status='failed',error=str(e),message='저장한 달까지는 세계에 남았습니다.',updatedAt=time.time());self.store.update_job(j)
                except Exception:pass
            finally:
                with self.lock:
                    if self.current_job==jid:self.current_job=None
    return AdultRunner

class Adult:
    def __init__(self,app):self.app=app;self.store=app.store
    def adult_job(self):
        with self.store.connect() as db:
            for (payload,) in db.execute('SELECT payload FROM jobs ORDER BY created DESC LIMIT 50'):
                j=json.loads(payload)
                if j.get('adult'):return j
        return None
    def status(self,owned=False):
        with self.store.lock:   # world and job are committed together; read them together so 'waiting' never shows without its branch
            w=self.store.load();job=self.adult_job()
        ph,p=phase(w);pl=w.get('player') or {}
        decisions=sorted(world.player_decisions(w,p['id']),key=lambda d:(-d['month'],d['key']))[:20] if p else []
        return {'world':{'month':w['month'],'revision':w['revision']},'owned':owned,'phase':ph,'pending':pl.get('pending') if ph=='adult' else None,
                'settings':pl.get('settings') or world.player_defaults()['settings'],
                'kinds':[{'id':k,'name':v} for k,v in world.BRANCH_KINDS.items()],
                'policies':[{'id':k,'name':n,'description':d} for k,(n,d) in world.POLICIES.items()],
                'job':public_job(job),'decisions':decisions,'lifespan':world.lifespan(p) if p else None}
    def _settled(self,w,revision):
        if type(revision) is not int or revision!=w['revision']:raise ValueError('세계 상태가 바뀌었습니다. 화면을 새로 확인한 뒤 골라 주세요.')
        runner=self.app.runner
        with runner.lock:
            if runner.thread and runner.thread.is_alive():raise ValueError('이전 계산을 정리하는 중입니다. 잠시 뒤 다시 골라 주세요.')
        if self.store.active():raise ValueError('진행 중인 작업을 먼저 끝내거나 취소해 주세요.')
    def _start(self,j):
        try:self.app.runner.start(j)
        except Exception:
            self.store.cancel_job(j['id']);raise
        return public_job(self.store.get_job(j['id']))
    def advance(self,months,revision):
        with self.app.operations,self.store.lock:
            w=self.store.load();self._settled(w,revision);ph,p=phase(w)
            if ph!='adult':raise ValueError('16세 이름 선언을 마친 살아 있는 내 인물만 성인 진행을 할 수 있습니다.')
            if w['player'].get('pending'):raise ValueError('기다리는 갈림길에 먼저 답해 주세요.')
            until=months=='next'   # F5: stops at the next branch (no auto setting needed); the player gets control back after answering it
            if until:months=NEXT_LIMIT
            elif months not in ADVANCE_MONTHS or type(months) is not int:raise ValueError('진행은 1개월·12개월·60개월·다음 갈림길까지 중에서 골라 주세요.')
            if months==60 and not until and not w['player']['settings'].get('allAuto'):raise ValueError('5년 연속 진행은 "모든 갈림길 자동"을 켠 뒤에 할 수 있습니다.')
            j=self.store.new_job('rules',months);j.update(adult={'person':p['id']},untilBranch=until,expect=w['revision'],message='다음 갈림길까지 살아갑니다.' if until else '내 인물의 달을 준비합니다.')
            self.store.update_job(j);return self._start(j)
    def answer(self,key,choice,revision):
        with self.app.operations,self.store.lock:
            w=self.store.load()
            if type(revision) is not int or revision!=w['revision']:raise ValueError('세계 상태가 바뀌었습니다. 화면을 새로 확인한 뒤 골라 주세요.')
            if self.store.active():raise ValueError('진행 중인 작업을 먼저 끝내거나 취소해 주세요.')
            runner=self.app.runner
            with runner.lock:
                if runner.thread and runner.thread.is_alive():raise ValueError('이전 계산을 정리하는 중입니다. 잠시 뒤 다시 골라 주세요.')
            ph,p=phase(w);pend=(w.get('player') or {}).get('pending')
            if ph!='adult' or not pend or pend.get('key')!=key:raise ValueError('기다리는 갈림길이 아닙니다. 화면을 새로 확인해 주세요.')
            valid={o['id'] for o in pend['options'] if not o['disabled']}
            if choice!='auto' and choice not in valid:raise ValueError('고를 수 있는 선택지가 아닙니다.')
            rev=w['revision'];w['player']['answers'][key]={'choice':choice,'by':'auto' if choice=='auto' else 'player'};w['player']['pending']=None;w['revision']+=1
            j=self.adult_job();resume=j and j['status']=='waiting' and j['completedMonths']<j['months']
            if resume:
                if j.get('untilBranch'):j['months']=j['completedMonths']+1   # finish the answered month, then hand control back
                j.update(status='queued',expect=w['revision'],message='답을 반영해 같은 달부터 이어 갑니다.',updatedAt=time.time())
            self.store.commit(w,rev,j if resume else None)
            return self._start(j) if resume else public_job(j)
    def settings(self,data,revision):
        with self.app.operations,self.store.lock:
            w=self.store.load();self._settled(w,revision);ph,p=phase(w)
            if ph not in ('adult','child'):raise ValueError('살아 있는 내 인물이 있어야 자동 설정을 바꿀 수 있습니다.')
            all_auto,kinds,policy=data.get('allAuto'),data.get('autoKinds'),data.get('policy')
            if not isinstance(all_auto,bool) or not isinstance(kinds,list) or not set(kinds)<=set(world.BRANCH_KINDS) or policy not in world.POLICIES:raise ValueError('자동 설정 값을 다시 확인해 주세요.')
            st=w['player']['settings'];rev=w['revision']
            if policy!=st.get('policy'):st['policyYear']=w['month']//12
            st.update(allAuto=all_auto,autoKinds=[k for k in world.BRANCH_KINDS if k in kinds],policy=policy)
            world.emit(w,'branch_settings',[p['id']],f"{p['name']}의 진행 설정: {'모든 갈림길 자동' if all_auto else '자동 '+str(len(st['autoKinds']))+'종류'} · 방침 {world.POLICIES[policy][0]}.",**st)
            w['revision']+=1;self.store.commit(w,rev)
        return self.status(True)
    def resume(self):
        """A failed run (an error in some month) starts again from its last saved month."""
        with self.app.operations:
            j=self.adult_job()
            if not j or j['status']!='failed':raise ValueError('이어 갈 실패한 성인 진행이 없습니다.')
            runner=self.app.runner
            with runner.lock:   # never turn a failed run into a cancelled one just because the last run is still finishing
                if runner.thread and runner.thread.is_alive():raise ValueError('이전 계산을 정리하는 중입니다. 잠시 뒤 다시 골라 주세요.')
            w=self.store.load();j.update(status='queued',error=None,expect=w['revision'],message='저장한 해부터 다시 이어 갑니다.',updatedAt=time.time());self.store.update_job(j)
            try:runner.start(j)
            except Exception:
                j.update(status='failed',message='이어 하기를 시작하지 못했습니다. 잠시 뒤 다시 시도해 주세요.',updatedAt=time.time());self.store.update_job(j);raise
            return public_job(self.store.get_job(j['id']))
    def cancel(self):
        j=self.adult_job()
        if not j or j['status'] not in ('queued','running','waiting','failed'):raise ValueError('진행 중인 성인 진행이 없습니다.')
        if j['status'] in ('waiting','failed'):self.store.cancel_job(j['id'])   # a waiting branch stays answerable; a failed run keeps its saved months
        else:self.app.runner.cancel(j['id'])
        return public_job(self.store.get_job(j['id']))

def install(App,Handler):
    """Installed after afterlife.py, so this runner wraps the spectator and childhood runners."""
    original_init,original_advance=App.__init__,App.advance
    def init(app,*args,**kwargs):
        original_init(app,*args,**kwargs)
        app.runner=adult_runner(type(app.runner))(app.store,app.claude);app.adult=Adult(app)
        configure=app.clock.configure
        def guarded_clock(data):   # K: the world clock runs only while there is no living adult player
            if data.get('enabled') and phase(app.store.load())[0]=='adult':raise ValueError('내 인물이 살아 있는 동안에는 /play 성인 화면에서 직접 진행합니다. 자동 시계를 켤 수 없습니다.')
            return configure(data)
        app.clock.configure=guarded_clock
    def advance(app,*args,**kwargs):
        if phase(app.store.load())[0]=='adult':raise ValueError('내 인물이 살아 있는 동안에는 /play 성인 화면에서 진행해 주세요.')
        return original_advance(app,*args,**kwargs)
    App.__init__,App.advance=init,advance
    get,post=Handler.do_GET,Handler.do_POST
    def request_ok(h):
        host=h.headers.get('Host','');origin=h.headers.get('Origin')
        if host not in [f'127.0.0.1:{h.server.server_port}',f'localhost:{h.server.server_port}'] or origin and origin!='http://'+host:raise PermissionError('이 컴퓨터의 플레이 화면에서 요청해 주세요.')
    def owned(h):
        cookie=h.headers.get('Cookie');admin=h.app.authority.authenticated(cookie)
        return admin or (hasattr(h.app,'childhood') and h.app.childhood.owner(cookie,admin))
    def adult_get(h):
        if urlsplit(h.path).path!='/api/adult':return get(h)
        try:request_ok(h);return h.send(h.app.adult.status(owned(h)))
        except PermissionError as e:return h.send({'error':str(e)},403)
        except (ValueError,KeyError,TypeError) as e:return h.send({'error':str(e)},400)
    def adult_post(h):
        path=urlsplit(h.path).path
        if not path.startswith('/api/adult/'):return post(h)
        try:
            request_ok(h);length=int(h.headers.get('Content-Length','0'))
            if not 0<=length<=4096:raise ValueError('요청이 너무 큽니다.')
            data=json.loads(h.rfile.read(length) or b'{}')
            if not isinstance(data,dict):raise ValueError('요청 내용을 다시 확인해 주세요.')
            if not owned(h):raise PermissionError('이 삶을 시작한 브라우저에서 이어가거나 관리자 인증을 해 주세요.')
            service=h.app.adult
            if path=='/api/adult/advance':return h.send(service.advance(data.get('months'),data.get('revision')),202)
            if path=='/api/adult/answer':return h.send(service.answer(data.get('key'),data.get('choice'),data.get('revision')),202)
            if path=='/api/adult/settings':return h.send(service.settings(data,data.get('revision')))
            if path=='/api/adult/cancel':return h.send(service.cancel())
            if path=='/api/adult/resume':return h.send(service.resume(),202)
            return h.send({'error':'알 수 없는 요청입니다.'},404)
        except PermissionError as e:return h.send({'error':str(e)},403)
        except (ValueError,KeyError,TypeError) as e:return h.send({'error':str(e)},400)
    Handler.do_GET,Handler.do_POST=adult_get,adult_post

