"""플레이어 번호·프로필·대표 캐릭터 API(schema 26). 보기는 이 컴퓨터 누구나, 바꾸기는 이 삶을 시작한 브라우저나 관리자만."""
import json
from urllib.parse import urlsplit
import world

def name(w,pid):
    p=w['people'].get(pid);return p['name'] if p else None

class Profile:
    def __init__(self,app):self.app=app;self.store=app.store
    def status(self):
        w=self.store.load();return {'profile':world.profile_view(w),'world':{'revision':w['revision'],'month':w['month']}}
    def realm(self):
        """나라 화면용: 정치 구조·특수 건물·신탁·전설의 전당·기념물·짓는 중인 공사·나라 살림. 없는 기능(옛 schema)은 빈 값."""
        w=self.store.load();s=w.get('schema',3)
        return {'world':{'revision':w['revision'],'month':w['month'],'schema':s},
                'polity':world.polity_view(w) if s>=26 else {},'specialty':world.specialty_view(w) if s>=26 else {},'oracle':world.oracle_view(w) if s>=26 else None,'witch':world.witch_view(w) if s>=29 else None,
                'legends':w.get('legends',[]),'statecraft':w.get('statecraft',{}),
                'monuments':[{**m,'overseerName':name(w,m['overseer'])} for m in w.get('monuments',[])],   # 감독 이름도 함께(없으면 None)
                'projects':{c:{**pr,'overseerName':name(w,pr['overseer'])} for c,pr in w.get('projects',{}).items()}}
    def _change(self,revision,fn):
        with self.app.operations,self.store.lock:
            w=self.store.load()
            if revision!=w['revision']:raise ValueError('그사이 세계가 바뀌었습니다. 화면을 새로 고친 뒤 다시 해 주세요.')
            if not w.get('profileNow'):raise ValueError('아직 플레이어 번호가 없습니다. 먼저 삶을 시작해 주세요.')
            fn(w);rev=w['revision'];w['revision']+=1;self.store.commit(w,rev)
        return self.status()
    def name(self,name,revision):return self._change(revision,lambda w:world.profile_name(w,name))
    def avatar(self,pid,revision):return self._change(revision,lambda w:world.profile_avatar(w,pid))

def install(App,Handler):
    """서버 고리 하나: /api/profile·/api/realm 보기와 /api/profile/name, /api/profile/avatar 바꾸기."""
    original_init=App.__init__
    def init(app,*args,**kwargs):
        original_init(app,*args,**kwargs);app.profile=Profile(app)
    App.__init__=init
    get,post=Handler.do_GET,Handler.do_POST
    def request_ok(h):
        host=h.headers.get('Host','');origin=h.headers.get('Origin')
        if host not in [f'127.0.0.1:{h.server.server_port}',f'localhost:{h.server.server_port}'] or origin and origin!='http://'+host:raise PermissionError('이 컴퓨터의 플레이 화면에서 요청해 주세요.')
    def owned(h):
        cookie=h.headers.get('Cookie');admin=h.app.authority.authenticated(cookie)
        return admin or (hasattr(h.app,'childhood') and h.app.childhood.owner(cookie,admin))
    def profile_get(h):
        path=urlsplit(h.path).path
        if path not in ('/api/profile','/api/realm'):return get(h)
        try:request_ok(h);return h.send(h.app.profile.status() if path=='/api/profile' else h.app.profile.realm())   # 보기는 이 컴퓨터 누구나
        except PermissionError as e:return h.send({'error':str(e)},403)
    def profile_post(h):
        path=urlsplit(h.path).path
        if path not in ('/api/profile/name','/api/profile/avatar'):return post(h)
        try:
            request_ok(h);length=int(h.headers.get('Content-Length','0'))
            if not 0<=length<=2048:raise ValueError('요청이 너무 큽니다.')
            data=json.loads(h.rfile.read(length) or b'{}')
            if not isinstance(data,dict):raise ValueError('요청 내용을 다시 확인해 주세요.')
            if not owned(h):raise PermissionError('이 삶을 시작한 브라우저에서 바꾸거나 관리자 인증을 해 주세요.')
            if path=='/api/profile/name':return h.send(h.app.profile.name(data.get('name'),data.get('revision')))
            return h.send(h.app.profile.avatar(data.get('person'),data.get('revision')))
        except PermissionError as e:return h.send({'error':str(e)},403)
        except (ValueError,KeyError,TypeError) as e:return h.send({'error':str(e)},400)
    Handler.do_GET=profile_get;Handler.do_POST=profile_post

