 function hero(){const p=data.person,c=data.campaign;const labels={choice:'올해의 선택',ready:'선택 저장됨',growing:'자라는 중',naming:'내 이름을 정하는 날',complete:'이어지는 성년의 삶',ended:'남겨진 삶'};return `<section class="hero"><div class="hero-copy"><div class="eyebrow">${esc(p.id)} / ${c.origin==='orphan'?'구호원에서 시작한 아이':'가족에게서 태어난 아이'}</div><h1>${esc(p.name)}의 ${c.phase==='ended'?'남겨진 삶':c.phase==='complete'?'이어지는 삶':'어린 날'}</h1><div class="age">${p.age}<small> 세</small><span class="phase-label">${labels[c.phase]||'삶의 기록'}</span></div><div class="identity"><span>${esc(p.race)} · ${p.sex==='F'?'여':'남'}</span><span>태어난 곳 <b>${esc(p.birthTownName||'기록 없음')}</b></span><span>지금 사는 곳 <b>${esc(p.townName||p.region)}</b></span></div></div>${backgroundMarkup()}</section><div class="meter"><i style="width:${Math.min(100,p.age/16*100)}%"></i></div>${worldline()}<p class="note">${esc(p.birthStory||'출생 당시의 기록과 지금의 가족 관계가 함께 남습니다.')}</p>${c.phase!=='complete'?lifespanNote(p)+personMarks(p):''}`;}
 function side(){const p=data.person,c=data.campaign,n=data.names;const rel=(ids,label)=>`<div class="kin"><small>${label}</small>${ids.length?ids.map(id=>`${esc(n[id]||id)} <small>${esc(id)}</small>`).join(' · '):'아직 알려진 기록이 없습니다.'}</div>`;return `<aside><section class="panel"><div class="eyebrow">내 생활</div><div class="facts"><div><span>건강</span><strong>${Math.round(p.health)}</strong></div><div><span>식량</span><strong>${p.food}<small>일분</small></strong></div><div><span>보호 재산</span><strong>${silver(p.trust)}</strong></div><div><span>직접 관리하는 돈</span><strong>${silver(p.cash)}</strong></div><div><span>이어진 후원 누계</span><strong>${silver(c.supportTotal)}</strong></div><div><span>내 채무</span><strong>${silver(p.debt)}</strong></div></div><small>재산 단위는 은화입니다. 공동 기금에 나눈 후원도 누계에 포함합니다.</small></section><section class="panel"><h3>이어지는 가족</h3>${rel(p.biologicalParents,'친부모')}${rel(p.legalParents,'지금의 법적 부모')}${rel(p.guardian?[p.guardian]:[],'현재 보호자')}<p><small>보호와 혈육은 서로 다른 기록으로 남습니다.</small></p></section><section class="panel"><h3>배워서 남긴 것</h3>${Object.entries(SK).map(([k,n])=>`<div class="skill"><span>${n}</span><b>수련 ${p.skills[k]||0}</b></div>`).join('')}<p><small>배움은 내 숙련으로 쌓습니다. 부모의 숙련과 점수는 복사되지 않습니다.</small></p></section></aside>`;}
