  return `<section class="panel" aria-label="성인 진행 상황"><h3>${labels[j.status]||'진행 상황'}</h3><div class="progress" role="progressbar" aria-label="성인 생활 진행" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.round(percent)}"><i style="width:${percent}%"></i></div><p class="status-text">${j.untilBranch&&adultRunning()?`${Math.floor(computed/12)+1}년째 · 갈림길을 기다리는 중<br>`:''}${done}/${total}개월 저장${adultRunning()?` · ${computed}/${total}개월 계산`:``} · ${Math.round(percent)}%</p><p>${esc(j.message||'저장된 진행 상황입니다.')}</p>${j.error?`<p class="error" role="alert">${esc(j.error)}</p>`:failed?'<p class="error" role="alert">계산이 중단되었습니다. 저장한 지점에서 다시 시도하거나 이번 진행을 취소해 주세요.</p>':''}<div class="actions">${failed?`<button class="primary" data-adult-action="resume" ${resumeLocked?'disabled':''}>저장한 달부터 이어 하기</button>`:''}${cancel?`<button class="quiet" data-adult-action="cancel" ${adultLocked()?'disabled':''}>이번 진행 취소</button>`:''}</div><p><small>${guidance}</small></p></section>`;
 }
 function branchCard(){
