 }
 async function profileCommand(b){
  const action=b.dataset.profileAction;
  if(action==='reload'){profileData=null;profileError='';profileActionError='';await refresh(true);return;}
  if(profileLocked())return;
  const body={revision:profileData.world.revision};
  if(action==='name'){body.name=profileDraft??profileData.profile.name;if(!body.name.trim()||body.name.length>16){toast('프로필 이름은 1~16자로 적어 주세요.');return;}}
  else body.person=action==='best'?null:b.dataset.profilePerson;
  busy=true;mutation++;profileActionError='';render();
  try{profileData=await api('/api/profile/'+(action==='name'?'name':'avatar'),body);profileDraft=null;profileError='';profileActionError='';toast(action==='name'?'프로필 이름을 저장했습니다.':'대표 인물을 저장했습니다.');}
  catch(e){profileActionError=e.message;toast(e.message);}
