 }
 window.addEventListener('hashchange',()=>{profileMode=location.hash==='#profile';if(profileMode){archive=null;refresh(true);}render();});
 document.addEventListener('toggle',e=>{if(e.target.id==='auto-kind-details')autoKindsOpen=e.target.open;},true);
 function render(){if(!data)return;if(profileMode){$('#app').innerHTML=profileView();return;}$('#save-state').textContent='현재 세계에 저장됨';if(!data.campaign){$('#app').innerHTML=lobby();return;}const c=data.campaign,j=data.activeJob;let content=archive?archiveView():c.phase==='ended'?ended():j?.childhood?growing():c.phase==='naming'?naming():c.phase==='complete'?adultView():choices();$('#app').innerHTML=hero()+`${!data.owned?'<p class="note">이 삶을 시작한 브라우저에서 이어가 주세요. 관리자 인증으로도 현재 삶을 확인하고 이어갈 수 있습니다.</p>':''}<div class="layout"><div>${content}${archive||c.phase==='complete'?'':history()}</div>${side()}</div>`;}
 async function refresh(force=false){
  if(polling||busy){if(force)refreshPending=true;return;}polling=true;const version=mutation;
  try{
   const next=await api('/api/childhood');
   if(busy||version!==mutation)return;
   let nextAdult=null,nextAdultError='';
   if(next.campaign?.phase==='complete'){
    try{nextAdult=await api('/api/adult');if(nextAdult.phase!=='adult')nextAdultError='성년의 최신 상태를 확인하고 있습니다. 잠시 뒤 다시 확인해 주세요.';}
    catch(e){nextAdultError='성인 생활을 불러오지 못했습니다. '+e.message;}
   }
   if(busy||version!==mutation)return;
   let nextProfile=profileData,nextProfileError=profileError;
   if(profileMode&&(force||!profileData||profileData.world?.revision!==next.world.revision)){
