   }
   if(busy||version!==mutation)return;
   profileData=nextProfile;profileError=nextProfileError;
   data=next;adult=nextAdult;adultError=nextAdultError;adultNeedsRefresh=false;
   if(data.campaign?.phase!=='complete'){settingsDraft=null;adultActionError='';}
   if(data.campaign?.phase==='ended'){
    try{afterlife=await api('/api/afterlife');afterlifeError='';}
