    const j=spectateJob();
    if(j&&!spectating()){
     const range=spectateRange(j),key=JSON.stringify([data.person.id,j.id,range.from,range.to,j.status]);
     if(key!==periodKey){
      period=null;
      if(Number.isInteger(range.from)&&Number.isInteger(range.to)){
       try{period=await api(`/api/afterlife/period?from=${range.from}&to=${range.to}`);periodKey=key;periodError='';}
       catch(e){periodError='기간 요약을 불러오지 못했습니다. '+e.message;}
