   if(!busy&&(force||sig!==signature)){signature=sig;if(data.campaign?.choice){learning=data.campaign.choice.learning;support=data.campaign.choice.support;sponsor=data.campaign.choice.sponsor||'';}render();}
  }catch(e){if(data?.campaign?.phase==='complete'){adultError='삶의 최신 기록을 불러오지 못했습니다. '+e.message;render();}$('#save-state').textContent='연결 확인 중 · 저장한 기록 유지';if(!data)$('#app').innerHTML=`<div class="error">${esc(e.message)}</div>`;}finally{polling=false;if(refreshPending){refreshPending=false;await refresh(true);}}
 }
 document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled||busy)return;if(b.dataset.profileAction||b.dataset.profilePerson){await profileCommand(b);return;}if(b.dataset.adultAction||b.dataset.adultChoice!==undefined||b.dataset.adultMonths){await adultCommand(b);return;}if(b.dataset.course){learning=b.dataset.course;render();return;}if(b.dataset.deathChoice){deathChoice=b.dataset.deathChoice;render();return;}try{busy=true;mutation++;b.disabled=true;
