  if(b.dataset.action==='world'){try{localStorage.setItem('prot-live-selected',data.person.id);}catch(_){}location.href='/';return;}
 }catch(err){toast(err.message);}finally{busy=false;await refresh(true);}});
 document.addEventListener('input',e=>{if(e.target.id==='adult-name')nameDraft=e.target.value;if(e.target.id==='profile-name')profileDraft=e.target.value;});
