  Object.assign(KINDS,{quest_done:'모험 의뢰',treated:'치료',shop_opened:'가게 열기',loan_given:'돈을 빌려줌',loan_repaid:'빌린 돈을 갚음',loan_lost:'받지 못한 빚',retired:'은퇴',returned_to_work:'다시 일하기',job_change:'직업을 바꿈',job_lost:'일을 잃음',job_gained:'일을 얻음',grade_up:'등급이 오름',polity_election:'의회 선거',polity_speaker:'의장 취임',polity_purge:'숙청',exam_passed:'과거 급제',oracle_called:'신탁',oracle_companions:'용사 동료 모집',oracle_sealed:'마왕 봉인',immigrants_recruited:'정착 지원금과 이주민',family_allowance:'가족 수당',public_works:'공공사업',project_started:'큰 공사 시작',project_built:'기념물 완공',legend_made:'전설의 전당',fame_rose:'명성이 오름',windfall:'뜻밖의 행운'});
  let loading = false, error = '', requestId = 0, annualPage = 0, annualOpen = false;
  const numeric = v => typeof v === 'number' && Number.isFinite(v);
  const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const list = v => Array.isArray(v) ? v : [];
  const number = (v, digits = 0) => numeric(v) ? new Intl.NumberFormat('ko-KR',{maximumFractionDigits:digits}).format(v) : '기록 없음';
  const compact = v => new Intl.NumberFormat('ko-KR',{notation:'compact',maximumFractionDigits:1}).format(v);
  const money = v => numeric(v) ? number(v / 100, 2) : '기록 없음';
  const welfare = v => numeric(v) ? `${number(v * 100,1)}%` : '기록 없음';
  const date = m => numeric(m) ? `${Math.floor(m / 12) + 1}년 ${m % 12 + 1}월` : '날짜 기록 없음';
  const year = y => numeric(y) ? `${y + 1}년` : '연도 기록 없음';
  const empty = text => `<p class="empty">${esc(text)}</p>`;
  const countryRows = () => {
    const rows = new Map(list(data?.countries).map(c => [c.id,{...c}]));
    for (const a of list(data?.years)) for (const id of Object.keys(a.countries || {})) {
