  };
  const country = id => countryRows().find(c => c.id === id)?.name || (id ? '나라 이름 기록 없음' : '기록 없음');
  const countryName = id => esc(country(id));
  const chosen = () => countryRows().filter(c => selected === null || selected.has(c.id));
  const color = id => PALETTE[Math.max(0,countryRows().findIndex(c => c.id === id)) % PALETTE.length];
  const yearRows = () => list(data?.years).filter(a => numeric(a.year)).slice().sort((a,b) => a.year - b.year);
  const metricValue = (a,id,metric) => {
    const v = a.countries?.[id]?.[metric];
    return numeric(v) ? metric === 'treasury' ? v / 100 : metric === 'welfare' ? v * 100 : v : null;
  };
  function seasonChoices(base = data) {
    const rows = new Map();
    for (const s of [...list(base?.season?.past),...list(base?.seasons)]) if (numeric(s.index) && numeric(s.start) && numeric(s.end)) rows.set(s.index,s);
    const current = base?.season;
    if (numeric(current?.index) && numeric(current.start)) rows.set(current.index,{index:current.index,start:current.start,end:base.now,current:true});
