    }
    return {from:0,to:base.now};
  }
  async function read(query = '') {
    const res = await fetch('/api/chronicle' + query,{headers:{Accept:'application/json'},cache:'no-store'});
    const body = await res.json();
    if (!res.ok) throw Error(body.error || '세계의 기록을 불러오지 못했습니다.');
    if (!numeric(body.from) || !numeric(body.to) || !numeric(body.now) || !Array.isArray(body.years) || !Array.isArray(body.countries)) throw Error('연대기 기록의 형식을 확인하지 못했습니다.');
