  }
  function chart(metric, title, unit) {
    const rows = yearRows(), countries = chosen();
    const series = countries.map(c => {
      const segments = []; let segment = [], previous = null;
      for (const a of rows) {
        const v = metricValue(a,c.id,metric);
        if (v === null) {if (segment.length) segments.push(segment); segment = []; previous = null; continue;}
        if (previous !== null && a.year !== previous + 1) {segments.push(segment); segment = [];}
        segment.push({year:a.year,value:v}); previous = a.year;
      }
      if (segment.length) segments.push(segment);
      return {...c,segments};
    });
    const values = series.flatMap(c => c.segments.flatMap(s => s.map(p => p.value)));
    const heading = `<div class="chart-title"><h3>${title}</h3><small>${unit}</small></div>`;
    if (!countries.length) return `<figure>${heading}<p class="empty chart-empty">위에서 표시할 나라를 골라 주세요.</p></figure>`;
    if (!values.length) return `<figure>${heading}<p class="empty chart-empty">이 기간에는 선택한 나라의 ${title} 연말 기록이 없습니다. 지금 값은 아래 나라 현황에서 볼 수 있습니다.</p></figure>`;
    const lo = Math.min(0,...values), hi = Math.max(metric === 'welfare'?100:1,...values) * (metric === 'welfare'?1:1.12);
    const first = rows[0].year, last = rows.at(-1).year, x = y => 45 + (y - first) / Math.max(1,last - first) * 310, y = v => 182 - (v - lo) / (hi - lo) * 154;
    let drawing = '';
    for (let i = 0; i <= 4; i++) {
      const value = lo + (hi - lo) * i / 4, pos = y(value);
      drawing += `<line class="grid" x1="45" x2="355" y1="${pos}" y2="${pos}"/><text x="38" y="${pos + 4}" text-anchor="end">${esc(compact(value))}</text>`;
    }
    const ticks = [...new Set([first,Math.round((first + last) / 2),last])];
    for (const t of ticks) drawing += `<text x="${x(t)}" y="205" text-anchor="middle">${year(t)}</text>`;
    for (const c of series) {
      const dash = countryRows().findIndex(a => a.id === c.id) >= PALETTE.length ? '5 4' : '';
      for (const segment of c.segments) {
        if (segment.length > 1) drawing += `<path class="series" data-country="${esc(c.id)}" data-points="${segment.length}" stroke="${color(c.id)}" stroke-dasharray="${dash}" d="${segment.map((p,i) => `${i?'L':'M'}${x(p.year).toFixed(2)},${y(p.value).toFixed(2)}`).join(' ')}"/>`;
        const markers = segment.length <= 35 ? segment : [segment[0],segment.at(-1)];
        for (const p of markers) drawing += `<circle cx="${x(p.year)}" cy="${y(p.value)}" r="2.8" fill="${color(c.id)}"><title>${esc(c.name)} · ${year(p.year)} · ${number(p.value,2)}${unit}</title></circle>`;
      }
    }
    return `<figure data-metric="${metric}">${heading}<svg class="chart" viewBox="0 0 380 220" role="img" aria-labelledby="chart-${metric}-title chart-${metric}-desc"><title id="chart-${metric}-title">나라별 ${title} 변화</title><desc id="chart-${metric}-desc">${year(first)}부터 ${year(last)}까지의 연말 기록입니다. 기록 없는 해는 선을 잇지 않습니다. 아래 연도별 기록표에서 값을 읽을 수 있습니다.</desc>${drawing}</svg><figcaption class="chart-caption">연말에 남은 기록입니다. 선 위 점에 머물면 해당 값을 볼 수 있습니다.</figcaption></figure>`;
  }
