      const response=await fetch('/api/realm',{headers:{Accept:'application/json'},cache:'no-store'});
      const body=await response.json();
      if(!response.ok)throw Error(body.error||'나라 기록을 불러오지 못했습니다.');
      if(!body.world||!numeric(body.world.month))throw Error('나라 기록의 형식을 확인하지 못했습니다.');
