    }catch(e){if(id===realmRequest)realmError=/[가-힣]/.test(e.message||'')?e.message:'나라 기록을 불러오지 못했습니다. 연결을 확인하고 다시 눌러 주세요.';}
    finally{if(id===realmRequest){realmLoading=false;render();}}
  }
