  function voteRecords(pol){
    if(!pol.voteMode&&!Array.isArray(pol.votes))return '';
    const votes=list(pol.votes).slice(-6).reverse();
    return `<section class="vote-records"><h4>의회 표결</h4>${pol.voteMode?`<p>결정 방식 · ${esc(pol.voteMode)}</p>`:''}${votes.length?`<ol>${votes.map(v=>`<li><div class="vote-heading"><strong>${esc(v.name||'이름이 남지 않은 안건')}</strong><span class="badge ${v.passed===false?'war':''}">${v.passed===true?'통과':v.passed===false?'부결':'결과 기록 없음'}</span></div><small>${year(v.year)}</small><ul>${list(v.chambers).map(ch=>`<li>${esc(ch.name)} · 찬성 ${number(ch.yes)}표 · 반대 ${number(ch.no)}표</li>`).join('')}</ul>${v.veto?`<p class="vote-veto">거부권 행사 · ${esc(v.veto)}</p>`:''}</li>`).join('')}</ol><p class="records-note">남아 있는 최근 표결 ${number(votes.length)}건입니다. 의회별 찬반 수를 보여 주며, 기권은 찬반 어느 쪽에도 더하지 않습니다.</p>`:empty('아직 남아 있는 표결 기록이 없습니다.')}</section>`;
  }
  function witchBanner(){
    const w=realm?.witch;if(!w)return '';
    const person=p=>p?`${esc(p.name||'이름 기록 없음')}${p.country?' · '+esc(p.country):''}${p.alive===false?' · 사망':''}`:'아직 정해지지 않았습니다.';
    const status={growing:'하얀마녀가 자라고 있습니다',journey:'봉인을 강화하러 가는 길',done:'하얀마녀 일행의 기록'};
    const result=w.result,notDeparted=result?.noParty===true;
    const timing=numeric(w.visit)&&w.visit>=0?`<p>${w.status==='growing'?'출발 예정':notDeparted?'출발을 계획했던 때':'출발'} · ${date(w.visit)}</p>`:'';
    const periods=[['weakUntil','봉인 약화가 이어지고 있습니다'],['darkUntil','대습격이 이어지고 있습니다']].filter(([key])=>numeric(w[key])&&w[key]>=0&&numeric(realm.world.month)&&w[key]>=realm.world.month).map(([key,label])=>`<p class="notice">${label}. ${date(w[key])}까지입니다.</p>`).join('');
    const outcome=notDeparted?'<p class="notice">일행을 꾸리지 못해 출발하지 못했습니다.</p>':result?`<p class="witch-result">${result.win===true?'봉인 강화에 성공했습니다.':result.win===false?'봉인 강화에 실패했습니다.':'아직 결과가 확인되지 않았습니다.'}${numeric(result.month)?' · '+date(result.month):''}${numeric(result.chance)?`<br>당시 성공 가능성 ${number(result.chance*100)}%`:''}${Array.isArray(result.dead)?` · 희생 ${number(result.dead.length)}명`:''}</p>`:'';
    return `<article class="card witch-banner"><div class="eyebrow">시즌 ${number(w.season)} · 하얀마녀</div><h3>${esc(status[w.status]||'하얀마녀의 기록')}</h3><p><strong>하얀마녀</strong> · ${person(w.witch)}</p>${w.leader?`<p><strong>일행을 이끈 사람</strong> · ${person(w.leader)}</p>`:''}<h4>함께한 동료</h4>${list(w.party).length?`<ul>${list(w.party).map(p=>`<li>${p?person(p):'이름 기록이 없는 동료'}</li>`).join('')}</ul>`:empty(w.status==='growing'?'아직 일행을 꾸리기 전입니다.':'기록된 동료가 없습니다.')}${timing}${outcome}${periods}</article>`;
  }
  function realmView(){
    const err=realmError?`<div class="error" role="alert">${esc(realmError)}${realm?'<p>아래에는 마지막으로 읽은 나라 기록을 유지합니다.</p>':''}<button data-action="realm-retry">나라 기록 다시 불러오기</button></div>`:'';
    if(!realm)return `<section id="realm"><div class="section-heading"><h2>나라와 세계의 이야기</h2></div>${err}${realmLoading?'<p role="status">지금의 나라 기록을 불러오는 중입니다…</p>':''}</section>`;
    const ids=[...new Set([...Object.keys(realm.polity||{}),...Object.keys(realm.specialty||{}),...Object.keys(realm.statecraft||{})])];
    const countryCards=ids.map(id=>{
      const pol=realm.polity?.[id],sp=realm.specialty?.[id],st=realm.world.schema>=27?realm.statecraft?.[id]:null;
      const current=list(data?.countries).find(c=>c.id===id);
      const body=`${current?`<p>지금 인구 ${number(current.alive)}명 · 국고 ${money(current.treasury)}은화</p>`:''}${pol?`<p>${esc(pol.structure)}${pol.suspended?' · 의회 활동 중단':''}</p><div class="chambers">${list(pol.chambers).map(ch=>{const speaker=list(ch.members).find(p=>p.id===ch.speaker);return `<article><h4>${esc(ch.name)} · ${number(ch.seats)}석</h4>${ch.speakerTitle||ch.speaker?`<p>${esc(ch.speakerTitle||'의장')} · ${esc(speaker?.name||(ch.speaker?'이름 기록 없음':'공석'))}</p>`:''}<p class="realm-members">의원 · ${list(ch.members).map(p=>esc(p.name)).join(' · ')||'공석'}</p>${numeric(ch.termEnd)?`<small>임기 끝 ${date(ch.termEnd)}</small>`:''}</article>`;}).join('')}</div>${voteRecords(pol)}`:''}${sp?`<h4>나라의 돈줄</h4><ul>${list(sp.buildings).map(b=>`<li>${esc(b.name)}${b.town?' · '+esc(b.town):''} · ${b.open?(b.damaged?'피해 복구 중':'운영 중'):'운영 중단'}</li>`).join('')}</ul>${numeric(sp.lastIncome)?`<p>지난해 특산 수입 ${money(sp.lastIncome)}은화</p>`:''}${sp.guard?`<p class="records-note">침공을 막는 근거 · ${esc(sp.guard)}</p>`:''}`:''}${st?`<h4>나라 살림</h4><p>목표 인구 ${number(st.target)}명 · 받아들인 이주민 누계 ${number(st.recruited)}명</p><p>가족 수당을 받은 부부 누계 ${number(st.benefits)}쌍 · 살림 지출 누계 ${money(st.spent)}은화</p>${st.boost?'<p>나라 급료가 늘어난 상태입니다.</p>':''}`:''}`;
      return details('country:'+id,`<b>${esc(pol?.country||sp?.country||country(id))}</b>${pol?.structure?`<small>${esc(pol.structure)}</small>`:''}`,body);
    }).join('');
    const preserved=realm.world.schema>=27?`<article class="card"><h3>시즌을 넘어 남는 이름과 건물</h3><p class="records-note">아래는 지금까지 보존된 전체 기록입니다. 위의 기간 필터로 과거의 명예를 숨기지 않습니다.</p>${details('legends',`전설의 전당 · ${number(list(realm.legends).length)}건`,list(realm.legends).length?`<ul>${list(realm.legends).slice().reverse().map(l=>`<li><b>${esc(l.name)}</b> · ${esc(l.deed)}<br><small>시즌 ${number(l.season)} · ${date(l.month)} · ${countryName(l.country)}</small></li>`).join('')}</ul>`:empty('아직 전설의 전당에 오른 이름이 없습니다.'))}${details('monuments',`남겨진 기념물 · ${number(list(realm.monuments).length)}곳`,list(realm.monuments).length?`<ul>${list(realm.monuments).map(m=>`<li>${esc(m.name)} · ${countryName(m.country)}<br><small>시즌 ${number(m.season)} · ${date(m.built)} 완공${m.overseerName?' · 감독 '+esc(m.overseerName):''}</small></li>`).join('')}</ul>`:empty('아직 완공된 기념물이 없습니다.'))}${details('projects',`짓는 중인 큰 공사 · ${number(entries(realm.projects).length)}곳`,entries(realm.projects).length?`<ul>${entries(realm.projects).map(([id,p])=>`<li>${esc(p.name)} · ${countryName(id)}<br><small>${date(p.start)} 시작 · ${date(p.end)} 완공 예정${p.overseerName?' · 감독 '+esc(p.overseerName):''}</small></li>`).join('')}</ul>`:empty('지금 짓는 큰 공사가 없습니다.'))}</article>`:'';
    return `<section id="realm"><div class="section-heading"><h2>나라와 세계의 이야기</h2><small>현재의 정치·살림과 보존된 공적</small></div><p class="records-note">${date(realm.world.month)}에 읽은 현재 모습입니다. 나라의 인구·국고 추이는 위의 ‘나라의 변화’에서 볼 수 있습니다.${data&&realm.world.month!==data.now?' 연대기와 읽은 시점이 다릅니다. 최신 기록을 새로고침해 주세요.':''}</p>${err}${realmLoading?'<p role="status">나라 기록을 새로 읽는 중입니다…</p>':''}<div class="world-stories">${oracleBanner()}${witchBanner()}</div><div class="realm-countries">${countryCards||empty('아직 남아 있는 나라별 기록이 없습니다.')}</div>${preserved}</section>`;
  }
  function render(focusId) {
    root.setAttribute('aria-busy',String(loading));
    root.innerHTML = `<section class="intro"><div class="eyebrow">세계에 남은 시간</div><h1>한 사람의 삶을 넘어,<br>계속 이어지는 연대기</h1><p>나라의 흥망과 가문의 계보, 내가 남긴 선택을 한 권의 기록으로 돌아봅니다.</p><span class="read-only">시간을 진행하지 않는 기록 보기</span></section>${controls()}${data?`<nav class="section-nav" aria-label="연대기 목차"><a href="#changes">나라의 변화</a><a href="#realm">나라와 세계 이야기</a><a href="#history">사건 연표</a><a href="#families">가문과 계보</a><a href="#lives">시즌과 나의 삶</a></nav>${changes()}${realmView()}${history()}${families()}${lives()}`:!error?'<p class="loading" role="status">보존된 기록을 읽고 있습니다…</p>':''}`;
    if (focusId) document.getElementById(focusId)?.focus({preventScroll:true});
  }
  document.addEventListener('change',event => {
    const el = event.target;
    if (el.id === 'period') {period = el.value; load();}
    else if (el.id === 'event-kind') {kind = el.value;worldEventType='all';render(el.id);}
    else if (el.id === 'world-event-type') {worldEventType=el.value;render(el.id);}
    else if (el.dataset.country !== undefined && data) {
      if (selected === null) selected = new Set(countryRows().map(c => c.id));
      if (el.checked) selected.add(el.dataset.country); else selected.delete(el.dataset.country);
      render(el.id);
    }
  });
  document.addEventListener('click',event => {
    const el = event.target.closest('[data-action]');
    if (!el || el.disabled) return;
    if (el.dataset.action === 'realm-retry') loadRealm();
    else if (el.dataset.action === 'refresh') {load(true);loadRealm();}
    else if (el.dataset.action === 'retry') load(!data);
    else if (el.dataset.action === 'all-countries') {selected = null; render();}
    else if (el.dataset.action === 'no-countries') {selected = new Set(); render();}
    else if (el.dataset.action === 'annual-newer') {annualPage = Math.max(0,annualPage - 1); render('annual-newer');}
    else if (el.dataset.action === 'annual-older') {annualPage++; render('annual-older');}
  });
  document.addEventListener('toggle',event => {if (event.target.id === 'annual-records') annualOpen = event.target.open;},true);
  document.addEventListener('toggle',event=>{const id=event.target.dataset?.realmDetail;if(id){if(event.target.open)realmOpen.add(id);else realmOpen.delete(id);}},true);
  load();loadRealm();
})();

web/chronicle.css:
:root{color-scheme:dark;--bg:#101b19;--panel:#1b2b25;--panel-light:#20342c;--ink:#f0ead8;--muted:#b5c3b9;--gold:#dfc68c;--line:#41554a;--mint:#9fceaf;font:15px/1.8 "Malgun Gothic","Apple SD Gothic Neo",sans-serif;color:var(--ink);background:var(--bg)}
*{box-sizing:border-box}body{margin:0}a{color:var(--gold);text-decoration:none}button,select,input{font:inherit;color:inherit}button,select{border:1px solid var(--line);border-radius:5px;background:#243b30;padding:9px 14px}button{cursor:pointer}button:disabled{opacity:.5;cursor:wait}a:focus-visible,button:focus-visible,select:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid var(--gold);outline-offset:4px}input{accent-color:var(--gold)}
.site-header{display:flex;justify-content:space-between;align-items:center;gap:24px;padding:20px max(5%,calc((100% - 1320px)/2));border-bottom:1px solid var(--line);background:#17261f}.brand{display:flex;align-items:center;gap:13px;color:var(--ink);font:19px Georgia,"Batang",serif;min-width:0}.brand b{font-size:32px;color:var(--gold);border:1px solid #86784e;padding:1px 9px}.brand small{display:block;margin-top:8px;font:11px "Malgun Gothic",sans-serif;letter-spacing:2px;color:var(--muted)}nav{display:flex;gap:22px;flex-wrap:wrap;font-size:13px}nav [aria-current]{color:var(--ink);border-bottom:1px solid var(--gold)}
main{max-width:1320px;margin:auto;padding:46px 4% 70px;min-width:0}.eyebrow{color:var(--gold);letter-spacing:3px;font-size:11px;font-weight:bold}.intro{padding-bottom:30px;border-bottom:1px solid var(--line);margin-bottom:24px}.intro h1{font:clamp(30px,4.1vw,48px)/1.35 Georgia,"Batang",serif;margin:14px 0}.intro p{color:var(--muted);max-width:65ch;margin:10px 0}.read-only{display:inline-block;border:1px solid #5c6c54;padding:4px 10px;color:var(--mint);font-size:12px;border-radius:20px}.toolbar{display:flex;align-items:end;justify-content:space-between;gap:16px;flex-wrap:wrap;margin:24px 0 10px}.field{display:flex;flex-direction:column;gap:6px}.field span{color:var(--muted);font-size:12px}.toolbar select{max-width:100%;min-width:230px}.range-label{font-size:13px;color:var(--muted);margin:8px 0 20px}.section-nav{display:flex;gap:12px;flex-wrap:wrap;padding:0 0 20px;border-bottom:1px solid var(--line);margin-bottom:30px}.section-nav a{font-size:13px;padding:5px 12px;border:1px solid var(--line);border-radius:20px}.notice,.error{padding:14px 18px;border-left:3px solid var(--gold);background:#26372c;border-radius:3px;margin:18px 0}.error{border-color:#f0a7a1;background:#3a2726;color:#ffcec8}.error button{margin-top:10px}.loading{padding:70px 20px;text-align:center;color:var(--muted)}
section{scroll-margin-top:20px;min-width:0}.section-heading{display:flex;align-items:baseline;justify-content:space-between;gap:15px;flex-wrap:wrap;margin:36px 0 16px}.section-heading h2{font:26px/1.4 Georgia,"Batang",serif;margin:0}.section-heading small,.muted,small{color:var(--muted)}h3{font-size:17px;line-height:1.5;margin:0 0 12px}p{overflow-wrap:anywhere}fieldset{min-width:0;border:1px solid var(--line);padding:14px 16px;border-radius:8px;margin:0 0 18px}legend{color:var(--muted);font-size:12px;padding:0 8px}.country-picker{display:flex;gap:10px 20px;flex-wrap:wrap;align-items:center}.country-picker label{display:flex;align-items:center;gap:7px;font-size:13px;cursor:pointer;overflow-wrap:anywhere;max-width:100%}.swatch{width:18px;height:3px;flex:none;display:inline-block;background:var(--swatch)}.country-tools{display:flex;gap:14px;margin-top:12px}.text-button{padding:0;background:none;border:0;color:var(--gold);font-size:12px;text-decoration:underline;text-underline-offset:4px}
.chart-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.card,figure{background:var(--panel);border:1px solid var(--line);border-radius:8px;padding:22px;min-width:0;margin:0}.chart-title{display:flex;justify-content:space-between;gap:10px;margin-bottom:12px}.chart-title h3{margin:0}.chart-title small{font-size:11px}.chart{display:block;width:100%;height:auto;overflow:visible}.chart text{fill:var(--muted);font:10px "Malgun Gothic",sans-serif}.chart .grid{stroke:#3a5044;stroke-dasharray:3 4;stroke-width:1}.chart .series{fill:none;stroke-width:2.4;stroke-linejoin:round;stroke-linecap:round;vector-effect:non-scaling-stroke}.chart-caption{font-size:11px;color:var(--muted);min-height:40px;line-height:1.7;margin:10px 0 0}.empty{color:var(--muted);padding:22px 0;margin:0}.chart-empty{min-height:190px;display:flex;align-items:center;font-size:13px}.table-scroll{overflow-x:auto;max-width:100%;border:1px solid var(--line);border-radius:8px;margin-top:20px;background:var(--panel)}table{border-collapse:collapse;width:100%;font-size:13px}caption{padding:16px;text-align:left;color:var(--muted);font-size:12px}th,td{padding:13px 16px;border-bottom:1px solid #35493d;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{color:var(--gold);font-weight:normal;white-space:nowrap}tbody tr:last-child td{border-bottom:0}.current-table{min-width:640px}.current-table small{display:block}.numeric{font-variant-numeric:tabular-nums}.badge{display:inline-block;padding:1px 7px;border:1px solid #63755b;border-radius:12px;font-size:11px;margin:2px 4px 2px 0;color:var(--mint)}.badge.war{border-color:#90654a;color:#ffd1a9}
.two-col{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.card-stack{display:grid;gap:12px}.war-card{border-left:3px solid #ce9d78}.war-card p{margin:8px 0;font-size:13px}.war-card small{display:block}.era-list{list-style:none;padding:0;margin:0}.era-list li{padding:12px 0;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;font-size:13px}.era-list li:last-child{border:0}.timeline-toolbar{display:flex;justify-content:space-between;align-items:end;gap:16px;flex-wrap:wrap;margin:22px 0 16px}.timeline-toolbar p{margin:0;font-size:12px;color:var(--muted)}.timeline{list-style:none;padding:0;margin:0;border-left:1px solid #6c7655;margin-left:5px}.timeline li{position:relative;padding:0 0 22px 24px;overflow-wrap:anywhere}.timeline li:before{content:"";position:absolute;width:7px;height:7px;border-radius:50%;background:var(--gold);left:-4px;top:10px}.timeline small{font-size:11px}.timeline p{margin:5px 0 0;font-size:14px}.timeline .kind{color:var(--gold);margin-left:12px}.records-note{font-size:12px;color:var(--muted);margin:16px 0}
.family-grid,.life-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.family-card .founder{border-top:1px solid var(--line);margin-top:14px;padding-top:12px;font-size:13px}.facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.facts small{display:block;font-size:11px}.facts strong{font-size:18px;font-weight:normal;font-variant-numeric:tabular-nums}.title-list{display:grid;gap:12px;margin-top:20px}details.card{padding:0}summary{cursor:pointer;list-style:revert;padding:18px 22px;overflow-wrap:anywhere}summary strong{margin-right:10px}summary small{display:block;margin-left:18px}.succession{padding:0 22px 18px;margin:0 0 0 30px;font-size:13px}.succession li{padding:8px 0 8px 6px}.succession small{display:block}.season-card{margin-bottom:14px}.season-card ol{margin:10px 0 0;padding-left:22px}.season-card li{padding:6px 0;font-size:13px}.season-card li span{float:right;color:var(--gold);padding-left:12px}.life-card h3{font:21px Georgia,"Batang",serif}.life-card p{font-size:13px;margin:8px 0}.life-card .descendants{font-size:25px;color:var(--gold);margin-right:6px}.life-card small{font-size:11px}.subheading{margin:26px 0 15px}.annual-table{min-width:520px}.annual-table td{padding:10px 13px}.annual-table small{display:block}.annual-pages{display:flex;justify-content:space-between;align-items:center;gap:12px;margin:12px 0;font-size:12px}.annual-pages button{font-size:12px;padding:6px 10px}footer{border-top:1px solid var(--line);padding:28px 5%;text-align:center;font-size:12px;color:var(--muted)}
