bridge.py:
"""휴대폰 판: 브라우저 안(파이오다이드)에서 진짜 서버의 요청 처리기를 그대로 돌린다.
- 화면이 보내는 요청을 server.py의 Handler에 넣고, 나온 응답을 화면에 돌려준다. 게임 규칙은 컴퓨터 판과 같다.
- 브라우저 안에서는 스레드를 띄울 수 없으므로, 스레드는 응답을 보낸 뒤 차례로 실행한다(drain).
- 저장은 /save 폴더(브라우저 저장소와 연결)에 한다. 쿠키(내 인물 열쇠)도 같은 폴더에 둔다."""
import http.client, io, json, os, sys, threading
from http.cookies import SimpleCookie
from pathlib import Path

PORT=8770;HOST=f'127.0.0.1:{PORT}'
SAVE=Path(os.environ.get('PROT_SAVE','/save'));JAR=SAVE/'cookies.json'   # 컴퓨터에서 시험할 때는 환경 변수로 바꾼다
_later=[]

class LaterThread:
    """응답을 먼저 보내고 나중에 실행하는 스레드 대신."""
    def __init__(self,group=None,target=None,name=None,args=(),kwargs=None,daemon=None):
        self.target,self.args,self.kwargs,self.name,self.daemon=target,args,kwargs or {},name,daemon;self.alive=False
    def start(self):self.alive=True;_later.append(self)
    def is_alive(self):return self.alive
    def join(self,timeout=None):pass
    def run_now(self):
        try:self.target(*self.args,**self.kwargs)
        finally:self.alive=False
threading.Thread=LaterThread

sys.path.insert(0,os.environ.get('PROT_APP','/app'))
import server   # 아동기·죽음 뒤·성인·프로필 연결은 server.py가 불러올 때 함께 설치된다

class FakeServer:server_port=PORT
SERVER=FakeServer();SERVER.app=server.App(SAVE/'world.sqlite3');SERVER.app.clock.configure({'enabled':False})   # 혼자 하기와 같다: 시간은 누를 때만 흐른다

def _jar():
    try:return json.loads(JAR.read_text(encoding='utf-8'))
    except Exception:return {}

def _keep(cookies):
    jar=_jar()
    for raw in cookies:
        c=SimpleCookie();c.load(raw)
        for k,m in c.items():
            if m['max-age'] in ('0',0):jar.pop(k,None)
            else:jar[k]=m.value
    JAR.write_text(json.dumps(jar),encoding='utf-8')

def handle(method,path,body=b''):
    """요청 하나를 처리해 (상태, 내용 종류, 본문)을 돌려준다."""
    h=server.Handler.__new__(server.Handler)
    h.server=SERVER;h.client_address=('127.0.0.1',0);h.request_version='HTTP/1.1';h.command=method;h.path=path;h.requestline=f'{method} {path} HTTP/1.1';h.close_connection=True
    m=http.client.HTTPMessage();m['Host']=HOST
    jar=_jar()
    if jar:m['Cookie']='; '.join(f'{k}={v}' for k,v in jar.items())
    body=bytes(body or b'')
    if method=='POST':m['Content-Type']='application/json';m['Content-Length']=str(len(body))
    h.headers=m;h.rfile=io.BytesIO(body);h.wfile=io.BytesIO()
    (h.do_POST if method=='POST' else h.do_GET)()
    head,_,out=h.wfile.getvalue().partition(b'\r\n\r\n')
    lines=head.decode('latin-1').split('\r\n');status=int(lines[0].split()[1]);kind='application/octet-stream';cookies=[]
    for line in lines[1:]:
        k,_,v=line.partition(': ')
        if k.lower()=='content-type':kind=v
        elif k.lower()=='set-cookie':cookies.append(v)
    if cookies:_keep(cookies)
    return status,kind,out

def pending():return len(_later)

def drain():
    """응답 뒤로 미룬 일(한 달 진행 등)을 끝까지 실행한다."""
    n=0
    while _later:_later.pop(0).run_now();n+=1
    return n

def handle_text(method,path,body=''):
    """화면 일꾼용: 본문을 글자로 주고받는다(그림은 엔진을 거치지 않는다)."""
    status,kind,out=handle(method,path,body.encode('utf-8') if isinstance(body,str) else body)
    tidy()
    return [status,kind,out.decode('utf-8',errors='replace')]

def tidy(keep=3):
    """휴대폰 저장 공간을 아끼려고 자동 백업은 최근 몇 개만 남긴다(컴퓨터 판은 그대로 다 남긴다)."""
    folder=SAVE/'backups'
    if folder.is_dir():
        for old in sorted(folder.glob('*.sqlite3'),key=lambda p:p.stat().st_mtime)[:-keep]:old.unlink(missing_ok=True)
